import{m as r,l}from"./use-stream-BymiQWv0.js";const c={"physics:physics-c1":{summary:"Units & Measurements sets the language of physics — SI units, dimensions and error analysis. It is a small chapter with big marks in both NEET and JEE.",keyPoints:["Seven base SI quantities: length (m), mass (kg), time (s), current (A), temperature (K), amount (mol), luminous intensity (cd).","Dimensions of common quantities: force [MLT⁻²], work [ML²T⁻²], pressure [ML⁻¹T⁻²].","Dimensional analysis checks equations and derives relations, but constants like k in F = kma can't be found by it.","Accuracy vs precision: accuracy is closeness to true value; precision is consistency of measurements.","Vernier calliper least count = 1 MSD − 1 VSD; screw gauge LC = pitch ÷ number of circular divisions."],formulas:[{name:"Dimensional formula",formula:"Derive from the defining relation, e.g. v = s/t → [LT⁻¹]"},{name:"Vernier least count",formula:"LC = 1 MSD − 1 VSD = 0.1 mm (standard calliper)"},{name:"Screw gauge least count",formula:"LC = pitch / (divisions on circular scale)"}],glossary:[{term:"Dimension",def:"Powers to which base quantities are raised in a physical quantity.",hindi:"विमा"},{term:"Least count",def:"Smallest value a measuring instrument can read.",hindi:"अल्पतमांक"},{term:"Significant figures",def:"Digits that carry meaningful information about precision, including the last uncertain digit.",hindi:"सार्थक अंक"}],mistakes:["Forgetting that zero at the end of a number is significant only if it comes after the decimal (e.g. 4500 vs 4.500 × 10³).","Applying dimensional analysis to find dimensionless constants — it cannot do that."],pyqs:[{q:"The dimensional formula of Planck's constant h is:",options:["[ML²T⁻¹]","[ML²T⁻²]","[MLT⁻¹]","[ML⁻¹T²]"],answer:0,explanation:"E = hν gives h = E/ν = [ML²T⁻²]/[T⁻¹] = [ML²T⁻¹]."},{q:"A vernier calliper has 20 divisions on its vernier scale matching 19 main scale divisions, each of 1 mm. Its least count is:",options:["0.05 mm","0.1 mm","0.01 mm","0.5 mm"],answer:0,explanation:"LC = 1 MSD − 1 VSD = 1 − 19/20 = 0.05 mm."}],tip:"Memorise 10–12 standard dimensional formulae — nearly every year one direct question appears."},"physics:physics-c2":{summary:"Motion in a Straight Line builds kinematics on distance, displacement, velocity and acceleration, ending with the three equations of motion and their graphs.",keyPoints:["Displacement is a vector (change in position); distance is the scalar path length.","Average velocity = displacement/time; average speed = distance/time — equal only if motion is straight-line without reversal.","Three equations of uniform acceleration: v = u + at, s = ut + ½at², v² = u² + 2as.","Slope of position–time graph = velocity; slope of velocity–time graph = acceleration; area under v–t graph = displacement.","In free fall, a = g ≈ 9.8 m/s² downward regardless of mass (ignoring air resistance)."],formulas:[{name:"First equation",formula:"v = u + at"},{name:"Second equation",formula:"s = ut + ½at²"},{name:"Third equation",formula:"v² = u² + 2as"}],glossary:[{term:"Acceleration",def:"Rate of change of velocity; SI unit m/s².",hindi:"त्वरण"},{term:"Free fall",def:"Motion under gravity alone, a = g.",hindi:"मुक्त पतन"}],mistakes:["Using distance in place of displacement in v = s/t when motion reverses direction.","Forgetting the sign of g: take downward as negative consistently."],pyqs:[{q:"A body starts from rest and accelerates at 2 m/s². Its velocity after 5 s is:",options:["10 m/s","5 m/s","25 m/s","20 m/s"],answer:0,explanation:"v = u + at = 0 + 2 × 5 = 10 m/s."},{q:"A ball is thrown up with 20 m/s. The maximum height reached is (g = 10 m/s²):",options:["20 m","40 m","10 m","30 m"],answer:0,explanation:"v² = u² − 2gh ⇒ 0 = 400 − 20h ⇒ h = 20 m."}],tip:"Draw the v–t graph for every kinematics problem — it often reveals the answer faster than algebra."},"physics:physics-c3":{summary:"Motion in a Plane generalises kinematics to two dimensions: vectors, projectile motion and uniform circular motion.",keyPoints:["Vectors add by triangle/parallelogram law; a vector multiplied by a scalar changes magnitude, not direction (sign flips if scalar is negative).","Projectile: horizontal motion is uniform (u cosθ), vertical motion has constant g — the two are independent.","Range R = u² sin2θ/g is maximum (Rmax = u²/g) at θ = 45°.","Time of flight T = 2u sinθ/g; maximum height H = u² sin²θ/(2g).","Uniform circular motion has constant speed but changing velocity; centripetal acceleration a = v²/r = ω²r directed to the centre."],formulas:[{name:"Range",formula:"R = u² sin2θ / g"},{name:"Max height",formula:"H = u² sin²θ / (2g)"},{name:"Time of flight",formula:"T = 2u sinθ / g"},{name:"Centripetal acceleration",formula:"a = v²/r = ω²r"}],glossary:[{term:"Projectile",def:"Body projected in air following a parabolic path under gravity.",hindi:"प्रक्षेप्य"},{term:"Centripetal force",def:"Net inward force keeping a body in circular motion.",hindi:"अभिकेंद्र बल"}],mistakes:["Treating horizontal velocity as affected by gravity — it is constant (g has no horizontal component).","Using θ = 45° as maximum range for all cases; it holds only for level ground."],pyqs:[{q:"A projectile's horizontal range is maximum when the angle of projection is:",options:["45°","30°","60°","90°"],answer:0,explanation:"R ∝ sin2θ, and sin2θ peaks at 2θ = 90°, i.e. θ = 45°."},{q:"For a particle in uniform circular motion, which quantity is constant?",options:["Speed","Velocity","Acceleration","Momentum"],answer:0,explanation:"Direction changes continuously, so velocity, acceleration and momentum change; only speed stays constant."}],tip:"In projectile PYQs, resolve into x and y components first and write the two independent motions."},"physics:physics-c4":{summary:"Laws of Motion covers Newton's three laws, momentum, friction and the dynamics needed to connect force with acceleration.",keyPoints:["First law: bodies keep their state unless a net external force acts (defines inertia and inertial frames).","Second law: F = dp/dt = ma (for constant mass).","Third law: action and reaction are equal, opposite and act on different bodies — they never cancel.","Impulse = F·Δt = change in momentum; area under F–t graph equals impulse.","Friction: f = μN (kinetic), fs ≤ μsN (static); friction opposes relative motion, always parallel to the contact surface."],formulas:[{name:"Newton's second law",formula:"F = ma"},{name:"Impulse",formula:"J = FΔt = Δp"},{name:"Friction (kinetic)",formula:"f = μN"}],glossary:[{term:"Inertia",def:"Tendency of a body to resist change in its state of motion.",hindi:"जड़त्व"},{term:"Impulse",def:"Force × time of action; equals change in momentum.",hindi:"आवेग"},{term:"Friction",def:"Force opposing relative motion between surfaces in contact.",hindi:"घर्षण"}],mistakes:["Cancelling action–reaction pairs as if they act on the same body.","Forgetting that static friction is self-adjusting up to μsN — it is not always μsN."],pyqs:[{q:"A 2 kg mass accelerates at 3 m/s² under a net force of:",options:["6 N","1.5 N","5 N","9 N"],answer:0,explanation:"F = ma = 2 × 3 = 6 N."},{q:"A ball of mass 0.1 kg moving at 10 m/s stops in 0.01 s on a wall. The impulse on the ball is:",options:["1 N·s","0.1 N·s","10 N·s","0.01 N·s"],answer:0,explanation:"J = Δp = 0 − (0.1 × 10) magnitude = 1 N·s (negative in direction of motion)."}],tip:"Always draw a free-body diagram and write F = ma along each axis before substituting."},"physics:physics-c5":{summary:"Work, Energy and Power connects force to energy — the work-energy theorem, conservation of mechanical energy, power and collisions.",keyPoints:["Work W = F·s = Fs cosθ; work is zero when force ⊥ displacement (e.g. centripetal force, tension in a pendulum string at an instant).","Work-energy theorem: net work = change in kinetic energy.","Mechanical energy is conserved when only conservative forces act (gravity, spring).","Power P = W/t = F·v; units: 1 hp = 746 W.","Elastic collision: KE conserved; perfectly inelastic: bodies stick, max KE loss."],formulas:[{name:"Work",formula:"W = Fs cosθ"},{name:"Kinetic energy",formula:"KE = ½mv²"},{name:"Gravitational PE",formula:"PE = mgh"},{name:"Power",formula:"P = W/t = F·v"}],glossary:[{term:"Conservative force",def:"Work done is path-independent; energy can be stored as PE (gravity, spring).",hindi:"संरक्षी बल"},{term:"Collision",def:"Interaction where bodies exchange momentum; elastic if KE is conserved.",hindi:"संघट्ट"}],mistakes:["Counting the sign of work wrongly: work done by friction is negative.","Applying conservation of mechanical energy when friction or other non-conservative forces act."],pyqs:[{q:"A force of 10 N acts at 60° to displacement of 5 m. Work done is:",options:["25 J","50 J","43.3 J","12.5 J"],answer:0,explanation:"W = 10 × 5 × cos60° = 50 × 0.5 = 25 J."},{q:"A 2 kg body falls freely from 5 m. Its speed just before ground (g = 10 m/s²) is:",options:["10 m/s","5 m/s","20 m/s","7 m/s"],answer:0,explanation:"mgh = ½mv² ⇒ v = √(2gh) = √100 = 10 m/s."}],tip:"In collisions, momentum is ALWAYS conserved — energy conservation applies only in elastic cases."},"physics:physics-c6":{summary:"Rotational Motion introduces the centre of mass, torque, angular momentum and moment of inertia — rotation's version of linear dynamics.",keyPoints:["Centre of mass of a system follows Newton's laws as if total mass were concentrated there.","Torque τ = r × F = Iα; angular momentum L = r × p = Iω.","Angular momentum is conserved when net external torque is zero (e.g. a spinning skater pulling arms in).","Moment of inertia depends on mass distribution about the axis: I = Σmr², I = MK² (K = radius of gyration).","Rolling without slipping: v = ωR; KE_total = ½mv²(1 + K²/R²)."],formulas:[{name:"Torque",formula:"τ = Iα = rF sinθ"},{name:"Angular momentum",formula:"L = Iω"},{name:"Rod about centre",formula:"I = ML²/12; about end: I = ML²/3"},{name:"Disc/cylinder",formula:"I = ½MR²"}],glossary:[{term:"Moment of inertia",def:"Rotational inertia; resistance to angular acceleration.",hindi:"जड़त्व आघूर्ण"},{term:"Torque",def:"Turning effect of a force; τ = r × F.",hindi:"बल आघूर्ण"}],mistakes:["Using the same I for different axes — always quote the axis with the value (e.g. rod about centre vs end).","Applying conservation of angular momentum when a net external torque (like friction) acts."],pyqs:[{q:"A solid sphere rolls without slipping. The fraction of its KE that is rotational is:",options:["2/7","2/5","1/2","5/7"],answer:0,explanation:"I = (2/5)MR², K²/R² = 2/5; rotational fraction = (2/5)/(1 + 2/5) = 2/7."},{q:"Angular momentum of a system is conserved when:",options:["net external torque is zero","net external force is zero","mechanical energy is zero","moment of inertia is constant"],answer:0,explanation:"τ_ext = dL/dt; if τ_ext = 0, L stays constant."}],tip:"Learn the standard I values (rod, ring, disc, sphere) — JEE/NEET assume you know them instantly."},"physics:physics-c7":{summary:"Gravitation covers the universal law, g and its variation, gravitational potential, satellites, escape velocity and Kepler's laws.",keyPoints:["F = Gm₁m₂/r² — universal, always attractive, independent of the medium between bodies.","g decreases with height and depth: g' = g(1 − 2h/R) for h << R; g' = g(1 − d/R) at depth d; g is zero at Earth's centre.","g is maximum at poles and minimum at the equator (rotation effect).","Escape velocity ve = √(2gR) ≈ 11.2 km/s — independent of the mass of the body.","Orbital velocity v = √(gR) for low orbits; geostationary satellites orbit at ~35,800 km above the equator."],formulas:[{name:"Gravitational force",formula:"F = Gm₁m₂/r²"},{name:"Escape velocity",formula:"ve = √(2GM/R) = √(2gR)"},{name:"Orbital velocity",formula:"v = √(GM/r)"},{name:"Gravitational PE",formula:"U = −GMm/r"}],glossary:[{term:"Escape velocity",def:"Minimum speed to leave a body's gravitational pull without further propulsion.",hindi:"पलायन वेग"},{term:"Geostationary satellite",def:"Satellite over the equator with T = 24 h, appearing stationary.",hindi:"भूस्थैतिक उपग्रह"}],mistakes:["Taking g as constant in problems about height/depth variation — use the correction formulas.","Confusing gravitational potential (−GM/r) with potential energy (−GMm/r)."],pyqs:[{q:"The escape velocity from Earth's surface is about:",options:["11.2 km/s","7.9 km/s","8.6 km/s","9.8 km/s"],answer:0,explanation:"ve = √(2gR) ≈ 11.2 km/s; 7.9 km/s is the low-orbit velocity."},{q:"At the centre of the Earth, the acceleration due to gravity is:",options:["zero","g","g/2","2g"],answer:0,explanation:"g' = g(1 − d/R); at d = R, g' = 0."}],tip:"Kepler's third law T² ∝ r³ is the basis of many satellite PYQs — spot the cube/square pattern."},"physics:physics-c8":{summary:"Mechanical Properties of Solids covers stress, strain, Hooke's law and the elastic moduli (Young's, shear, bulk).",keyPoints:["Stress = restoring force/area (N/m²); strain is dimensionless (fractional change).","Hooke's law: within elastic limit, stress ∝ strain.","Young's modulus Y = FL/(AΔL); describes stretching.","Shear modulus G = shear stress/shear strain; bulk modulus B = −ΔP/(ΔV/V); compressibility = 1/B.","Stress–strain curve: proportionality limit → elastic limit → yield point → breaking point; ductile vs brittle materials."],formulas:[{name:"Young's modulus",formula:"Y = FL / (AΔL)"},{name:"Bulk modulus",formula:"B = −VΔP / ΔV"},{name:"Elastic energy density",formula:"u = ½ × stress × strain = ½Y(strain)²"}],glossary:[{term:"Stress",def:"Restoring force per unit area.",hindi:"प्रतिबल"},{term:"Strain",def:"Fractional deformation of a body.",hindi:"विकृति"},{term:"Elastic limit",def:"Maximum stress for which the body returns to its original shape.",hindi:"प्रत्यास्थ सीमा"}],mistakes:["Using force instead of force/area in modulus formulas.","Forgetting that strain is unitless — answers are often pure ratios."],pyqs:[{q:"A wire of length 2 m and area 1 mm² stretches 1 mm under a 200 N load. Young's modulus is:",options:["4 × 10¹¹ N/m²","2 × 10¹¹ N/m²","1 × 10¹¹ N/m²","4 × 10¹⁰ N/m²"],answer:0,explanation:"Y = FL/(AΔL) = 200 × 2 / (10⁻⁶ × 10⁻³) = 4 × 10¹¹ N/m²."},{q:"The ability of a material to be drawn into wires is called:",options:["Ductility","Malleability","Elasticity","Plasticity"],answer:0,explanation:"Ductility is the ability to be drawn into thin wires; malleability is beating into sheets."}],tip:"Watch unit conversions (mm² → m², cm → m) — they are the favourite trap in these numericals."},"physics:physics-c9":{summary:"Mechanical Properties of Fluids covers pressure, Pascal's law, buoyancy, viscosity, Bernoulli's theorem and surface tension.",keyPoints:["Pascal's law: pressure applied to an enclosed fluid transmits equally in all directions (hydraulic lift).","Archimedes' principle: buoyant force = weight of displaced fluid.","Viscous force F = ηA(dv/dx); Stokes' law for a sphere F = 6πηrv; terminal velocity vₜ = 2r²(ρ−σ)g/(9η).","Bernoulli: P + ½ρv² + ρgh = constant (ideal, streamline flow) — explains aerofoil lift and venturi.","Surface tension γ = F/L (N/m); capillary rise h = 2γcosθ/(ρgr)."],formulas:[{name:"Pressure",formula:"P = P₀ + ρgh"},{name:"Stokes' law",formula:"F = 6πηrv"},{name:"Terminal velocity",formula:"vₜ = 2r²(ρ − σ)g / 9η"},{name:"Bernoulli",formula:"P + ½ρv² + ρgh = constant"}],glossary:[{term:"Buoyancy",def:"Upward force on a body immersed in a fluid, equal to the displaced fluid's weight.",hindi:"उत्प्लावन"},{term:"Viscosity",def:"Internal friction of a fluid opposing relative motion between layers.",hindi:"श्यानता"},{term:"Surface tension",def:"Force per unit length acting along a liquid surface.",hindi:"पृष्ठ तनाव"}],mistakes:["Using Bernoulli for turbulent or viscous flows — it assumes ideal, streamline flow.","Forgetting that buoyancy depends on the fluid's density, not the body's."],pyqs:[{q:"A sphere falls through a viscous liquid. Its terminal velocity is proportional to:",options:["r²","r","1/r","r³"],answer:0,explanation:"vₜ = 2r²(ρ−σ)g/(9η) ∝ r²."},{q:"Aeroplane wings experience lift mainly because of:",options:["Bernoulli's principle","Pascal's law","Archimedes' principle","Stokes' law"],answer:0,explanation:"Faster air above the wing lowers pressure, creating net upward force (Bernoulli)."}],tip:"The ½ρv² term appears constantly — remember Bernoulli's three terms: pressure + dynamic + potential."},"physics:physics-c10":{summary:"Thermal Properties of Matter spans temperature, thermal expansion, calorimetry, heat transfer and Newton's law of cooling.",keyPoints:["Linear expansion ΔL = L₀αΔT; area and volume expansion use 2α and 3α.","Calorimetry: heat gained = heat lost; Q = mcΔT; latent heat Q = mL during phase change.","Conduction Q/t = kAΔT/d; convection is fluid motion; radiation needs no medium (Stefan: P ∝ T⁴).","Newton's law of cooling: rate of cooling ∝ temperature difference with surroundings.","Water's anomalous expansion: maximum density at 4 °C."],formulas:[{name:"Linear expansion",formula:"ΔL = L₀ α ΔT"},{name:"Heat transfer (conduction)",formula:"Q/t = kAΔT/d"},{name:"Stefan-Boltzmann",formula:"P = σeAT⁴"}],glossary:[{term:"Calorimetry",def:"Measurement of heat transfer using a calorimeter.",hindi:"कैलोरीमिति"},{term:"Latent heat",def:"Heat absorbed/released during a phase change at constant temperature.",hindi:"गुप्त ऊष्मा"}],mistakes:["Adding mcΔT during a phase change — use mL there.","Treating blackbody emissivity e as 1 for every surface."],pyqs:[{q:"Heat required to melt 100 g of ice at 0 °C (L = 80 cal/g) is:",options:["8000 cal","800 cal","80 cal","1000 cal"],answer:0,explanation:"Q = mL = 100 × 80 = 8000 cal."},{q:"A copper rod conducts heat by:",options:["Conduction","Convection","Radiation","Advection"],answer:0,explanation:"Solids transfer heat mainly by conduction (free electrons + lattice vibration)."}],tip:"For calorimetry mixtures, write 'heat lost = heat gained' before touching numbers."},"physics:physics-c11":{summary:"Thermodynamics is about heat, work and internal energy — the first law, processes, heat engines and the second law.",keyPoints:["First law: ΔQ = ΔU + ΔW (heat added = internal energy change + work done by gas).","Isothermal (T constant): ΔU = 0, Q = W; adiabatic (Q = 0): ΔU = −W; isochoric (V constant): W = 0.","Work done by gas = area under P–V curve; cyclic process: ΔU = 0, net work = net heat.","Second law: heat cannot flow spontaneously from cold to hot; efficiency of any engine < 100%.","Carnot efficiency η = 1 − T₂/T₁ (absolute temperatures)."],formulas:[{name:"First law",formula:"ΔQ = ΔU + ΔW"},{name:"Work in isothermal process",formula:"W = nRT ln(V₂/V₁)"},{name:"Carnot efficiency",formula:"η = 1 − T₂/T₁"}],glossary:[{term:"Adiabatic process",def:"No heat exchange with surroundings (Q = 0).",hindi:"रुद्धोष्म प्रक्रम"},{term:"Isothermal process",def:"Constant temperature process.",hindi:"समतापी प्रक्रम"},{term:"Entropy",def:"Measure of disorder; isolated systems tend to increase it.",hindi:"एन्ट्रॉपी"}],mistakes:["Sign convention slips: work done BY the gas is positive in ΔQ = ΔU + ΔW (chemistry uses the opposite).","Forgetting T must be in kelvin in Carnot efficiency."],pyqs:[{q:"In an isothermal expansion of an ideal gas:",options:["ΔU = 0","Q = 0","ΔW = 0","ΔT > 0"],answer:0,explanation:"Internal energy of an ideal gas depends only on T, which is constant."},{q:"A Carnot engine works between 400 K and 300 K. Its efficiency is:",options:["25%","75%","33%","50%"],answer:0,explanation:"η = 1 − 300/400 = 0.25 = 25%."}],tip:"Draw the P–V diagram for process questions; the area under the curve IS the work."},"physics:physics-c12":{summary:"Kinetic Theory explains gas behaviour statistically — the ideal gas equation, kinetic interpretation of temperature and equipartition.",keyPoints:["Ideal gas: PV = nRT = NkT with k = R/NA = 1.38 × 10⁻²³ J/K.","Pressure P = (1/3)ρv̄²; average KE per molecule = (3/2)kT — temperature is a measure of mean KE.","RMS speed v_rms = √(3RT/M) — independent of pressure at fixed T.","Equipartition: each quadratic degree of freedom contributes ½kT of energy.","Mean free path λ = 1/(√2 πd²n) — decreases with density, increases with T at constant P."],formulas:[{name:"Ideal gas",formula:"PV = nRT = NkT"},{name:"RMS speed",formula:"v_rms = √(3RT/M)"},{name:"Mean KE of molecule",formula:"⟨KE⟩ = (3/2)kT"}],glossary:[{term:"Degrees of freedom",def:"Independent ways a molecule can store energy (translation, rotation, vibration).",hindi:"स्वातंत्र्य कोटि"},{term:"Mean free path",def:"Average distance a molecule travels between collisions.",hindi:"माध्य मुक्त पथ"}],mistakes:["Using molar mass in g instead of kg in v_rms = √(3RT/M).","Confusing rms speed with average or most probable speed."],pyqs:[{q:"The average kinetic energy of a gas molecule at temperature T is:",options:["(3/2)kT","(1/2)kT","(3/2)RT","kT"],answer:0,explanation:"Kinetic interpretation of temperature gives ⟨KE⟩ = (3/2)kT per molecule."},{q:"The rms speed of gas molecules is doubled when temperature (absolute) is:",options:["quadrupled","doubled","halved","tripled"],answer:0,explanation:"v_rms ∝ √T, so T must quadruple to double the speed."}],tip:"v_rms ∝ √(T/M) is the single most-repeated ratio in this chapter."},"physics:physics-c13":{summary:"Oscillations covers simple harmonic motion (SHM), its energy, pendulums, spring-mass systems and resonance.",keyPoints:["SHM: F = −kx, a = −ω²x; displacement x = A sin(ωt + φ).","In SHM, velocity leads displacement by 90°; acceleration is opposite to displacement.","Total energy E = ½kA² is constant; KE and PE trade off sinusoidally at twice the frequency.","Simple pendulum T = 2π√(L/g) (small angles); spring T = 2π√(m/k).","Resonance: amplitude peaks when driving frequency equals natural frequency."],formulas:[{name:"SHM equation",formula:"x = A sin(ωt + φ)"},{name:"Pendulum period",formula:"T = 2π√(L/g)"},{name:"Spring period",formula:"T = 2π√(m/k)"},{name:"Total energy",formula:"E = ½kA² = ½mω²A²"}],glossary:[{term:"Amplitude",def:"Maximum displacement from the mean position.",hindi:"आयाम"},{term:"Phase",def:"Argument of the sine function describing the state of oscillation.",hindi:"कला"},{term:"Resonance",def:"Large-amplitude response when driving frequency matches natural frequency.",hindi:"अनुनाद"}],mistakes:["Using T = 2π√(L/g) for large amplitudes — it is valid only for small oscillations.","Forgetting that in SHM both KE and PE oscillate at 2× the SHM frequency."],pyqs:[{q:"A simple pendulum of length 1 m on Earth (g = π² m/s²) has a period of:",options:["2 s","1 s","4 s","π s"],answer:0,explanation:"T = 2π√(1/π²) = 2 s."},{q:"In SHM, the acceleration is maximum when:",options:["displacement is maximum","velocity is maximum","KE is maximum","phase is 90°"],answer:0,explanation:"a = −ω²x, so a is maximum at extreme displacement."}],tip:"Remember the lead/lag relations: v leads x by 90°, a leads v by 90°."},"physics:physics-c14":{summary:"Waves covers the wave equation, superposition, standing waves on strings, beats and the Doppler effect.",keyPoints:["Wave speed on a string v = √(T/μ); sound speed v = √(B/ρ) in fluids.","Standing waves on a string fixed at both ends: λₙ = 2L/n, frequencies fₙ = nv/(2L) (harmonics).","Open organ pipe: all harmonics; closed pipe: only odd harmonics, f₁ = v/(4L).","Beats: two close frequencies produce amplitude beats at f = |f₁ − f₂|.","Doppler effect: apparent frequency changes when source/observer move; use sign conventions carefully."],formulas:[{name:"String wave speed",formula:"v = √(T/μ)"},{name:"String harmonics",formula:"fₙ = nv/(2L)"},{name:"Closed pipe fundamental",formula:"f₁ = v/(4L)"},{name:"Beat frequency",formula:"f = |f₁ − f₂|"}],glossary:[{term:"Wavelength",def:"Distance between successive identical points of a wave.",hindi:"तरंगदैर्ध्य"},{term:"Doppler effect",def:"Change in observed frequency due to relative motion of source and observer.",hindi:"डॉपलर प्रभाव"}],mistakes:["Using fₙ = nv/(2L) for closed pipes — those allow only odd harmonics (fₙ = (2n−1)v/(4L)).","Getting the Doppler sign wrong; define the direction from observer to source."],pyqs:[{q:"Two tuning forks of 512 Hz and 516 Hz sound together. The beat frequency is:",options:["4 Hz","514 Hz","2 Hz","8 Hz"],answer:0,explanation:"Beats = |516 − 512| = 4 Hz."},{q:"A string fixed at both ends vibrates in its fundamental mode. If its length is L, the fundamental wavelength is:",options:["2L","L","L/2","4L"],answer:0,explanation:"λ₁ = 2L for a string with nodes at both ends."}],tip:"For standing waves, first identify boundary conditions (fixed/free) — that decides which harmonics exist."},"physics:physics-c15":{summary:"Electric Charges and Fields introduces Coulomb's law, electric fields, dipoles, flux and Gauss's law.",keyPoints:["Coulomb's law F = kq₁q₂/r² with k = 1/(4πε₀) ≈ 9 × 10⁹ N·m²/C²; like charges repel.","Charge is quantised (e = 1.6 × 10⁻¹⁹ C) and conserved.","Electric field E = F/q = kQ/r²; field lines never cross, start at + and end at −.","Dipole: field on axis E = 2kp/r³, on equatorial line E = kp/r³ (p = q·2a).","Gauss's law: Φ = ∮E·dA = q_enc/ε₀ — use it for spheres, cylinders, sheets (E = σ/(2ε₀))."],formulas:[{name:"Coulomb's law",formula:"F = kq₁q₂/r²"},{name:"Point charge field",formula:"E = kQ/r²"},{name:"Dipole axial field",formula:"E = 2kp/r³"},{name:"Gauss's law",formula:"Φ = q_enc/ε₀"}],glossary:[{term:"Electric dipole",def:"Pair of equal and opposite charges separated by a small distance.",hindi:"विद्युत द्विध्रुव"},{term:"Electric flux",def:"Scalar measure of field lines crossing a surface; Φ = E·A.",hindi:"विद्युत फ्लक्स"}],mistakes:["Forgetting r is the centre-to-centre distance between charges.","Using 1/r³ for a point charge instead of 1/r² (1/r³ appears for dipoles)."],pyqs:[{q:"The force between two charges is F when they are distance r apart. If distance becomes 2r, force becomes:",options:["F/4","F/2","2F","4F"],answer:0,explanation:"F ∝ 1/r², so doubling r quarters the force."},{q:"The SI unit of electric flux is:",options:["N·m²/C","N/C","V/m","C/m²"],answer:0,explanation:"Φ = E·A ⇒ (N/C)(m²) = N·m²/C."}],tip:"Gauss's law questions are about choosing the right Gaussian surface — symmetry is everything."},"physics:physics-c16":{summary:"Electrostatic Potential and Capacitance covers potential, equipotential surfaces, capacitors, dielectrics and stored energy.",keyPoints:["Potential V = kQ/r; potential energy U = qV; work to move charge = qΔV.","Equipotential surfaces: no work to move along them; field is perpendicular to them.","Capacitance C = Q/V; parallel plate C = ε₀A/d; with dielectric C = κε₀A/d.","Series: 1/C = Σ1/Cᵢ (same Q); parallel: C = ΣCᵢ (same V).","Energy stored U = ½CV² = Q²/(2C); a dielectric increases capacitance and energy for fixed V."],formulas:[{name:"Potential of point charge",formula:"V = kQ/r"},{name:"Parallel plate capacitor",formula:"C = ε₀A/d"},{name:"Energy stored",formula:"U = ½CV²"}],glossary:[{term:"Capacitance",def:"Charge stored per unit potential difference.",hindi:"धारिता"},{term:"Dielectric",def:"Insulator that increases capacitance by polarisation.",hindi:"परावैद्युत"}],mistakes:["In series, adding capacitances directly (use reciprocals); in parallel, using reciprocals.","Forgetting that V is the same across parallel branches and Q the same in series."],pyqs:[{q:"Two capacitors of 2 μF and 3 μF are connected in series. The equivalent capacitance is:",options:["1.2 μF","5 μF","6 μF","0.8 μF"],answer:0,explanation:"1/C = 1/2 + 1/3 = 5/6 ⇒ C = 1.2 μF."},{q:"Energy stored in a capacitor is ½CV². If V doubles, energy becomes:",options:["4×","2×","½×","unchanged"],answer:0,explanation:"U ∝ V², so doubling V quadruples the energy."}],tip:"With a battery connected (fixed V), inserting a dielectric increases stored energy; disconnected (fixed Q), it decreases."},"physics:physics-c17":{summary:"Current Electricity covers Ohm's law, drift velocity, resistivity, combinations of resistors, Kirchhoff's laws and bridges.",keyPoints:["I = neAv_d; drift velocity v_d = eEτ/m.","Ohm's law V = IR is not universal (diodes, electrolytes violate it); resistance depends on geometry R = ρL/A.","Resistivity depends on material and temperature: ρ = ρ₀(1 + αΔT).","Series: R = ΣRᵢ; parallel: 1/R = Σ1/Rᵢ (equivalent is smaller than the smallest).","Kirchhoff: junction rule (ΣI = 0) + loop rule (ΣV = 0); Wheatstone bridge balances when P/Q = R/S."],formulas:[{name:"Ohm's law",formula:"V = IR"},{name:"Resistance",formula:"R = ρL/A"},{name:"Drift velocity",formula:"v_d = I/(neA)"},{name:"Bridge balance",formula:"P/Q = R/S"}],glossary:[{term:"Drift velocity",def:"Small average velocity of electrons opposite to the field.",hindi:"अपवाह वेग"},{term:"Resistivity",def:"Material property; R = ρL/A.",hindi:"प्रतिरोधकता"}],mistakes:["Adding series resistors in parallel formula and vice versa.","Sign errors in loop rule — fix a traversal direction and keep it consistent."],pyqs:[{q:"Three resistors of 2 Ω, 3 Ω and 6 Ω in parallel have equivalent resistance:",options:["1 Ω","11 Ω","0.5 Ω","2.4 Ω"],answer:0,explanation:"1/R = 1/2 + 1/3 + 1/6 = 1 ⇒ R = 1 Ω."},{q:"Wheatstone bridge is balanced when:",options:["P/Q = R/S","P/R = Q/S","P = Q = R = S","P + Q = R + S"],answer:0,explanation:"Balance condition: P/Q = R/S (no current through galvanometer)."}],tip:"Redraw complex circuits into clear series/parallel blocks before applying formulas."},"physics:physics-c18":{summary:"Moving Charges and Magnetism covers the Lorentz force, motion in fields, Biot-Savart law, Ampere's law, solenoids and the cyclotron.",keyPoints:["Lorentz force F = q(E + v × B); magnetic force does no work (it only changes direction).","Charged particle in a uniform B: circular motion with r = mv/(qB), T = 2πm/(qB) — T is speed-independent.","Biot-Savart: B = (μ₀/4π)(Idl×r̂/r²); long straight wire B = μ₀I/(2πr).","Ampere's law ∮B·dl = μ₀I_enc; solenoid B = μ₀nI; toroid B = μ₀nI.","Parallel currents attract if in the same direction, repel if opposite."],formulas:[{name:"Circular radius",formula:"r = mv/(qB)"},{name:"Straight wire field",formula:"B = μ₀I/(2πr)"},{name:"Solenoid field",formula:"B = μ₀nI"}],glossary:[{term:"Lorentz force",def:"Total force on a moving charge: electric + magnetic.",hindi:"लॉरेंज बल"},{term:"Cyclotron",def:"Device accelerating charged particles in a spiral using B and alternating E.",hindi:"साइक्लोट्रॉन"}],mistakes:["Using F = qvB for particles at rest — magnetic force needs v ≠ 0 and v not parallel to B.","Direction errors with v × B — use the right-hand rule consistently."],pyqs:[{q:"The time period of a charged particle in a uniform magnetic field is:",options:["independent of speed","proportional to speed","proportional to v²","inversely proportional to charge"],answer:0,explanation:"T = 2πm/(qB) has no v — higher speed means a larger circle in the same time."},{q:"Two parallel wires carry currents in the same direction. They:",options:["attract each other","repel each other","experience no force","rotate about each other"],answer:0,explanation:"Same-direction parallel currents attract."}],tip:"T = 2πm/(qB) being speed-independent is a classic assertion question."},"physics:physics-c19":{summary:"Magnetism and Matter deals with bar magnets, Earth's magnetism and the three classes of magnetic materials.",keyPoints:["A bar magnet is a dipole: field lines go from N to S outside, S to N inside.","Magnetic moment m = q_m × 2l; torque on a magnet in a field τ = m × B.","Earth's field: declination, dip (inclination) and horizontal component; tanδ = Bv/BH.","Ferromagnets (Fe, Co, Ni): strong attraction, retain magnetisation, Curie temperature destroys it.","Diamagnets (Bi, Cu): weakly repelled, μr slightly < 1; paramagnets (Al, Na): weakly attracted, μr slightly > 1."],formulas:[{name:"Torque on magnet",formula:"τ = mB sinθ"},{name:"Dip angle",formula:"tanδ = Bv/BH"}],glossary:[{term:"Diamagnetic",def:"Material weakly repelled by a magnet; paired electrons, no net moment.",hindi:"प्रतिचुंबकीय"},{term:"Curie temperature",def:"Temperature above which a ferromagnet becomes paramagnetic.",hindi:"क्यूरी ताप"}],mistakes:["Thinking all metals are ferromagnetic — only Fe, Co, Ni and a few alloys are.","Confusing magnetic moment direction with field direction for a solenoid/bar magnet."],pyqs:[{q:"The material that shows the strongest magnetism is:",options:["Ferromagnetic","Paramagnetic","Diamagnetic","Non-magnetic"],answer:0,explanation:"Ferromagnets have aligned domains giving strong net magnetisation."},{q:"Above the Curie temperature, a ferromagnet behaves as:",options:["a paramagnet","a diamagnet","a permanent magnet","a superconductor"],answer:0,explanation:"Thermal agitation destroys domain alignment, leaving paramagnetic behaviour."}],tip:"Remember the order of susceptibility: χ_ferro >> χ_para > 0 > χ_dia."},"physics:physics-c20":{summary:"Electromagnetic Induction covers Faraday's and Lenz's laws, motional EMF, inductance and eddy currents.",keyPoints:["Faraday's law: EMF = −dΦ/dt; the minus sign is Lenz's law (opposes the change producing it).","Motional EMF in a rod: ε = Bvl (with v ⊥ B ⊥ l).","Flux Φ = BA cosθ; changing B, A or θ all induce EMF.","Self inductance ε = −L dI/dt; mutual inductance couples two coils.","Eddy currents: induced currents in bulk conductors causing heating and damping (used in brakes, induction furnaces)."],formulas:[{name:"Faraday's law",formula:"ε = −dΦ/dt"},{name:"Motional EMF",formula:"ε = Bvl"},{name:"Self inductance EMF",formula:"ε = −L dI/dt"},{name:"Inductor energy",formula:"U = ½LI²"}],glossary:[{term:"Magnetic flux",def:"Φ = BA cosθ — field lines threading a loop.",hindi:"चुंबकीय फ्लक्स"},{term:"Eddy currents",def:"Circulating currents induced in bulk conductors by changing flux.",hindi:"भंवर धाराएँ"}],mistakes:["Ignoring Lenz's law direction in diagram questions — energy conservation demands opposition.","Using ε = Bvl when B is parallel to the plane of motion (θ matters)."],pyqs:[{q:"A rod of length 0.5 m moves at 4 m/s perpendicular to a 0.2 T field. The motional EMF is:",options:["0.4 V","0.2 V","0.8 V","2 V"],answer:0,explanation:"ε = Bvl = 0.2 × 4 × 0.5 = 0.4 V."},{q:"Lenz's law follows directly from:",options:["conservation of energy","conservation of charge","Coulomb's law","Ampere's law"],answer:0,explanation:"Opposing the change conserves energy — the induced current's field fights the cause."}],tip:"For flux questions, first ask: is B, A or cosθ changing? That tells you the source of EMF."},"physics:physics-c21":{summary:"Alternating Current covers RMS values, LCR circuits, resonance, power and transformers.",keyPoints:["RMS values: V_rms = V₀/√2, I_rms = I₀/√2 (sinusoidal); house supply 220 V is the RMS value.","Pure R: current in phase; pure L: current lags by 90°; pure C: current leads by 90°.","LCR series impedance Z = √(R² + (X_L − X_C)²); resonance at ω₀ = 1/√(LC) where Z = R (minimum).","Power P = V_rms I_rms cosφ; cosφ = R/Z; Q factor = ω₀L/R.","Transformer: Vs/Vp = Ns/Np; step-up increases voltage, decreases current (ideal, no losses)."],formulas:[{name:"RMS voltage",formula:"V_rms = V₀/√2"},{name:"Resonant frequency",formula:"ω₀ = 1/√(LC)"},{name:"Impedance",formula:"Z = √(R² + (X_L − X_C)²)"},{name:"Average power",formula:"P = V_rms I_rms cosφ"}],glossary:[{term:"Resonance",def:"X_L = X_C, current maximum and in phase with voltage.",hindi:"अनुनाद"},{term:"Transformer",def:"Device changing AC voltage using mutual induction.",hindi:"ट्रांसफॉर्मर"}],mistakes:["Using V₀ where V_rms is needed (or vice versa) in power formulas.","Thinking a transformer works on DC — it needs changing flux."],pyqs:[{q:"The peak value of 220 V AC mains is:",options:["311 V","220 V","155 V","440 V"],answer:0,explanation:"V₀ = V_rms × √2 = 220 × 1.414 ≈ 311 V."},{q:"In a series LCR circuit at resonance, the impedance is:",options:["minimum","maximum","infinite","zero"],answer:0,explanation:"X_L = X_C cancels, leaving Z = R — the minimum value."}],tip:"At resonance remember: Z = R, current maximum, and power factor = 1."},"physics:physics-c22":{summary:"Electromagnetic Waves covers how changing fields create waves, their properties and the spectrum.",keyPoints:["Maxwell: changing electric field generates magnetic field and vice versa — waves propagate at c = 1/√(μ₀ε₀).","EM waves are transverse; E ⊥ B ⊥ direction of propagation; E and B in phase.","Energy is equally shared between E and B fields; momentum p = U/c.","Spectrum (increasing frequency): radio < microwave < IR < visible < UV < X-ray < gamma.","Applications: microwaves (radar, cooking), X-rays (bone imaging), γ-rays (cancer therapy, sterilisation)."],formulas:[{name:"Speed of light",formula:"c = 1/√(μ₀ε₀) ≈ 3 × 10⁸ m/s"},{name:"Wave relation",formula:"c = νλ"},{name:"Energy density",formula:"u = ε₀E² = B²/μ₀"}],glossary:[{term:"Electromagnetic spectrum",def:"Full range of EM radiation ordered by frequency/wavelength.",hindi:"विद्युतचुंबकीय स्पेक्ट्रम"},{term:"Transverse wave",def:"Oscillations perpendicular to the direction of travel.",hindi:"अनुप्रस्थ तरंग"}],mistakes:["Saying E and B are perpendicular to each other AND in phase — they are both true.","Getting the spectrum order backwards — wavelength and frequency are inversely related."],pyqs:[{q:"Electromagnetic waves are produced by:",options:["accelerated charges","static charges","uniform currents","magnetic monopoles"],answer:0,explanation:"Only accelerating charges radiate EM waves."},{q:"Which has the longest wavelength?",options:["Radio waves","X-rays","Gamma rays","UV rays"],answer:0,explanation:"Radio waves have the lowest frequency and longest wavelength."}],tip:"Learn the spectrum as a ladder: R-M-I-V-U-X-G with a use for each band."},"physics:physics-c23":{summary:"Ray Optics covers reflection by mirrors, refraction by lenses and prisms, total internal reflection and optical instruments.",keyPoints:["Mirror formula 1/v + 1/u = 1/f with sign convention; f = R/2.","Lens formula 1/v − 1/u = 1/f; lens maker's formula with refractive index and radii.","Refractive index n = c/v = sin i/sin r (Snell's law).","Total internal reflection needs n₂ < n₁ and i > ic = sin⁻¹(n₂/n₁); used in optical fibres, mirage.","Prism: δ = i + e − A; minimum deviation when i = e; μ = sin((A+δm)/2)/sin(A/2).","Compound microscope and telescope magnifications — tube length relations."],formulas:[{name:"Mirror formula",formula:"1/v + 1/u = 1/f"},{name:"Lens formula",formula:"1/v − 1/u = 1/f"},{name:"Critical angle",formula:"sin ic = n₂/n₁"},{name:"Prism deviation",formula:"δ = i + e − A"}],glossary:[{term:"Total internal reflection",def:"Complete reflection when light travels from denser to rarer medium past the critical angle.",hindi:"पूर्ण आंतरिक परावर्तन"},{term:"Focal length",def:"Distance from the pole/optical centre to the principal focus.",hindi:"फोकस दूरी"}],mistakes:["Applying mirror formula to lenses without switching signs (mirror: v,u same side; lens: opposite).","Forgetting that a convex lens has positive f and a concave mirror negative f per convention."],pyqs:[{q:"A convex lens of focal length 20 cm forms an image at 30 cm. The object distance is:",options:["60 cm","12 cm","40 cm","50 cm"],answer:0,explanation:"1/30 − 1/u = 1/20 ⇒ 1/u = 1/30 − 1/20 = −1/60 ⇒ u = −60 cm."},{q:"Optical fibres work on the principle of:",options:["total internal reflection","refraction","dispersion","diffraction"],answer:0,explanation:"Light is trapped inside the fibre by repeated total internal reflection."}],tip:"Always write the sign convention explicitly before substituting in mirror/lens formulas."},"physics:physics-c24":{summary:"Wave Optics treats light as waves — Huygens principle, interference, diffraction and polarisation.",keyPoints:["Huygens principle: every point on a wavefront is a new source of secondary wavelets; explains reflection and refraction.","Young's double slit: fringe width β = λD/d; bright fringes at path difference nλ, dark at (2n−1)λ/2.","Coherent sources have constant phase difference — needed for sustained interference.","Diffraction: single slit minima at a sinθ = nλ; central maximum is twice as wide.","Polarisation proves light is transverse; intensity after polariser I = I₀cos²θ (Malus' law)."],formulas:[{name:"Fringe width",formula:"β = λD/d"},{name:"Single slit minima",formula:"a sinθ = nλ"},{name:"Malus' law",formula:"I = I₀ cos²θ"}],glossary:[{term:"Interference",def:"Superposition of coherent waves producing bright/dark fringes.",hindi:"व्यतिकरण"},{term:"Polarisation",def:"Restricting vibrations to one plane — only transverse waves polarise.",hindi:"ध्रुवण"}],mistakes:["Using the YDSE fringe formula for diffraction (and vice versa) — check the setup.","Thinking polarisation works for longitudinal waves — it cannot."],pyqs:[{q:"In YDSE, the fringe width is 1 mm with light of 500 nm and slit separation 0.5 mm. The screen distance is:",options:["1 m","2 m","0.5 m","4 m"],answer:0,explanation:"β = λD/d ⇒ D = βd/λ = 10⁻³ × 5×10⁻⁴ / 5×10⁻⁷ = 1 m."},{q:"Which phenomenon proves that light is a transverse wave?",options:["Polarisation","Refraction","Interference","Diffraction"],answer:0,explanation:"Only transverse waves can be polarised."}],tip:"Fringe width formula questions are free marks: β = λD/d, just watch the unit of λ (m, not nm)."},"physics:physics-c25":{summary:"Dual Nature of Radiation and Matter covers the photoelectric effect, Einstein's equation and de Broglie waves.",keyPoints:["Photoelectric effect: emission of electrons when light hits a metal; instantaneous, threshold frequency dependent.","Einstein: E = hν = φ + KE_max; KE_max = eV₀ (stopping potential).","Increasing intensity increases photocurrent, NOT electron energy; increasing frequency increases KE.","de Broglie wavelength λ = h/p = h/(mv); for electrons accelerated through V: λ = 12.27/√V Å.","Davisson-Germer experiment confirmed electron waves."],formulas:[{name:"Photoelectric equation",formula:"hν = φ + ½mv_max²"},{name:"Stopping potential",formula:"eV₀ = KE_max"},{name:"de Broglie wavelength",formula:"λ = h/p"}],glossary:[{term:"Work function",def:"Minimum energy needed to eject an electron from a metal surface.",hindi:"कार्य फलन"},{term:"Threshold frequency",def:"Minimum frequency for photoelectric emission.",hindi:"देहली आवृत्ति"}],mistakes:["Saying higher intensity means faster electrons — intensity changes the NUMBER, frequency changes the energy.","Using λ = h/mv for photons — photons travel at c, so p = hν/c."],pyqs:[{q:"The stopping potential for photoelectrons depends on:",options:["frequency of light","intensity of light","area of the metal","duration of exposure"],answer:0,explanation:"KE_max = eV₀ = hν − φ — only frequency (and the metal) matter."},{q:"The de Broglie wavelength of a particle is:",options:["inversely proportional to momentum","proportional to momentum","proportional to mass","independent of speed"],answer:0,explanation:"λ = h/p, so wavelength falls as momentum rises."}],tip:"Distinguish intensity effects (current) from frequency effects (energy) — a classic NEET/JEE trap."},"physics:physics-c26":{summary:"Atoms traces atomic models from Rutherford to Bohr, energy levels and the hydrogen spectrum.",keyPoints:["Rutherford: nucleus is tiny and positive, electrons orbit; most alpha particles pass straight through.","Bohr: electrons in quantised orbits; angular momentum mvr = nh/2π; energy levels Eₙ = −13.6/n² eV.","Radius rₙ = 0.529 n² Å; velocity vₙ = 2.18 × 10⁶/n m/s.","Energy emitted on transition: hν = Eᵢ − Eₖ; Lyman (UV), Balmer (visible), Paschen (IR) series.","Ionisation energy of hydrogen = 13.6 eV; excitation to n=∞ means ionisation."],formulas:[{name:"Energy levels",formula:"Eₙ = −13.6/n² eV"},{name:"Bohr radius",formula:"rₙ = 0.529 n² Å"},{name:"Transition energy",formula:"hν = Eᵢ − Eₖ"}],glossary:[{term:"Quantum number",def:"Integer labelling allowed orbits (n = 1, 2, 3…).",hindi:"क्वांटम संख्या"},{term:"Ionisation energy",def:"Energy to remove the electron from the ground state.",hindi:"आयनन ऊर्जा"}],mistakes:["Using the Rydberg formula with wrong series limits (Lyman ends at n=1, Balmer at n=2).","Forgetting that Eₙ is negative — emission energy is Eᵢ − Eₖ (positive)."],pyqs:[{q:"The ionisation energy of the hydrogen atom in the ground state is:",options:["13.6 eV","3.4 eV","10.2 eV","27.2 eV"],answer:0,explanation:"E₁ = −13.6 eV, so ionisation needs 13.6 eV."},{q:"The Balmer series of hydrogen lies in the:",options:["visible region","UV region","IR region","X-ray region"],answer:0,explanation:"Transitions to n = 2 fall in the visible range."}],tip:"Memorise E = −13.6/n² and r = 0.529n² Å — most Bohr questions reduce to these two."},"physics:physics-c27":{summary:"Nuclei covers nuclear structure, radioactivity, decay laws, fission, fusion and mass-energy equivalence.",keyPoints:["Nucleus: protons + neutrons; radius R = R₀A^(1/3) with R₀ ≈ 1.2 fm; density roughly constant.","Mass-energy: E = mc²; 1 amu ≈ 931 MeV.","Radioactive decay: N = N₀e^(−λt); half-life T₁/₂ = ln2/λ; mean life τ = 1/λ = T₁/₂/0.693.","α decay reduces A by 4, Z by 2; β⁻ converts n → p + e⁻ + ν̄; γ is high-energy photon emission.","Fission (heavy nucleus splits, e.g. U-235 + n) and fusion (light nuclei merge, e.g. sun's p-p chain) release binding energy."],formulas:[{name:"Decay law",formula:"N = N₀e^(−λt)"},{name:"Half-life",formula:"T₁/₂ = ln2/λ = 0.693/λ"},{name:"Nuclear radius",formula:"R = R₀A^(1/3)"},{name:"Mass-energy",formula:"E = mc²"}],glossary:[{term:"Half-life",def:"Time for half the nuclei to decay.",hindi:"अर्धायु काल"},{term:"Binding energy",def:"Energy holding nucleons together; BE = Δm·c².",hindi:"बंधन ऊर्जा"}],mistakes:["Confusing half-life with mean life — mean life τ = 1.44 × T₁/₂.","In α-decay, changing the mass number by 2 instead of 4."],pyqs:[{q:"The half-life of a radioactive substance is 10 days. After 30 days, the fraction remaining is:",options:["1/8","1/4","1/3","1/2"],answer:0,explanation:"30 days = 3 half-lives ⇒ (1/2)³ = 1/8."},{q:"The energy released in nuclear reactions comes from:",options:["mass defect converted via E = mc²","chemical bonds","kinetic energy of electrons","heat of the sun"],answer:0,explanation:"Mass defect Δm releases energy E = Δm·c²."}],tip:"Fraction remaining after n half-lives is always (1/2)ⁿ — the fastest route in most decay MCQs."},"physics:physics-c28":{summary:"Semiconductor Electronics covers p-n junctions, rectifiers, transistors, amplifiers and logic gates.",keyPoints:["p-n junction: depletion region with built-in potential; forward bias (p to +) conducts, reverse bias blocks.","Diode VI characteristic: knee voltage ~0.7 V for Si, 0.3 V for Ge.","Rectifiers: half-wave (1 diode) and full-wave (2 diodes, centre-tap or bridge) convert AC to DC.","Transistor: npn/pnp, three terminals; CE amplifier gives current and voltage gain; α = β/(β+1).","Logic gates: AND, OR, NOT, NAND, NOR, XOR — NAND and NOR are universal gates; truth tables are exam favourites."],formulas:[{name:"Transistor relation",formula:"I_E = I_B + I_C"},{name:"Gain relation",formula:"β = α/(1−α)"},{name:"Voltage gain (CE)",formula:"Av = β × R_L/R_in"}],glossary:[{term:"Depletion region",def:"Charge-free zone at a p-n junction with built-in field.",hindi:"अवक्षय क्षेत्र"},{term:"Logic gate",def:"Digital circuit implementing a Boolean operation.",hindi:"लॉजिक गेट"}],mistakes:["Saying current flows in both directions in a diode — it conducts only forward-biased (beyond knee).","Forgetting the truth table of NAND (AND then invert) in gate combination questions."],pyqs:[{q:"A p-n junction diode conducts when it is:",options:["forward biased","reverse biased","unbiased","always"],answer:0,explanation:"Forward bias reduces the barrier and allows majority carrier flow."},{q:"Which gate gives output 0 only when all inputs are 1?",options:["NAND","AND","OR","XOR"],answer:0,explanation:"NAND = NOT(AND): output 0 only for 1,1 inputs."}],tip:"For gate networks, break them into single gates and build the truth table step by step."}},m={"chemistry:chemistry-c1":{summary:"Some Basic Concepts of Chemistry builds the mole concept, stoichiometry and concentration terms — the arithmetic engine of the whole paper.",keyPoints:["1 mole = 6.022 × 10²³ particles; molar mass in g/mol equals molecular mass in amu.","n = given mass/molar mass = volume at STP/22.4 L = NA × molecules.","Limiting reagent: the reactant that runs out first determines product amount.","Percentage composition: % element = (mass of element/molar mass) × 100; empirical → molecular formula via n = molar mass/empirical mass.","Laws: conservation of mass, constant proportions, multiple proportions (Dalton), Gay-Lussac's volumes."],formulas:[{name:"Moles",formula:"n = m/M = V/22.4 (STP)"},{name:"Molarity",formula:"M = moles of solute / litres of solution"},{name:"Molality",formula:"m = moles of solute / kg of solvent"}],glossary:[{term:"Mole",def:"Amount containing Avogadro's number of entities.",hindi:"मोल"},{term:"Limiting reagent",def:"Reactant fully consumed, deciding the product yield.",hindi:"सीमांत अभिकर्मक"},{term:"Molarity",def:"Moles of solute per litre of solution.",hindi:"मोलरता"}],mistakes:["Using litre of solvent instead of solution for molarity.","Forgetting to balance the equation before stoichiometry — ratios come from coefficients."],pyqs:[{q:"The number of moles in 11 g of CO₂ (M = 44) is:",options:["0.25","0.5","1","2"],answer:0,explanation:"n = 11/44 = 0.25 mol."},{q:"Molarity of a solution with 4 g NaOH (M = 40) in 500 mL is:",options:["0.2 M","0.1 M","0.4 M","0.5 M"],answer:0,explanation:"n = 0.1 mol; M = 0.1/0.5 = 0.2 M."}],tip:"STP shortcut: 22.4 L per mole of gas saves a full step in gas stoichiometry."},"chemistry:chemistry-c2":{summary:"Structure of Atom covers atomic models, quantum numbers, orbitals and electronic configuration.",keyPoints:["Bohr model works for hydrogen-like species; de Broglie λ = h/mv and Heisenberg's uncertainty principle apply to all matter.","Quantum numbers: n (shell), l (subshell, 0 to n−1), ml (−l…+l), ms (±1/2) — each electron has a unique set.","Orbital capacities: s = 2, p = 6, d = 10, f = 14 electrons.","Aufbau (fill lowest energy first: 1s<2s<2p<3s<3p<4s<3d…), Pauli (no two electrons identical), Hund (fill orbitals singly first).","Stability: half-filled and fully filled subshells are extra stable (Cr, Cu exceptions)."],formulas:[{name:"Energy of H-like level",formula:"Eₙ = −13.6 Z²/n² eV"},{name:"de Broglie wavelength",formula:"λ = h/mv"},{name:"Max electrons in shell",formula:"2n²"}],glossary:[{term:"Quantum number",def:"Set of four numbers uniquely identifying an electron's state.",hindi:"क्वांटम संख्या"},{term:"Orbital",def:"Region with high probability of finding an electron.",hindi:"कक्षक"},{term:"Aufbau principle",def:"Electrons fill orbitals in increasing energy order.",hindi:"आफबाऊ सिद्धांत"}],mistakes:["Writing 3d before 4s in configuration order — energy fills 4s first but we write 3d first.","Forgetting Hund's rule for nitrogen's three 2p electrons."],pyqs:[{q:"The maximum number of electrons in an f-subshell is:",options:["14","10","6","2"],answer:0,explanation:"f orbitals: 7 orbitals × 2 electrons = 14."},{q:"The electronic configuration of Cr (Z = 24) is:",options:["[Ar] 3d⁵ 4s¹","[Ar] 3d⁴ 4s²","[Ar] 3d⁶","[Ar] 3d⁵ 4s²"],answer:0,explanation:"Half-filled 3d⁵ 4s¹ is more stable than 3d⁴ 4s²."}],tip:"Exceptions (Cr, Cu, Mo, Ag, Au) appear in NEET repeatedly — memorise the short list."},"chemistry:chemistry-c3":{summary:"Classification of Elements and Periodicity explains the periodic table and trends in atomic size, ionisation enthalpy, electron gain enthalpy and electronegativity.",keyPoints:["Modern periodic law: properties are a periodic function of atomic number; blocks s, p, d, f.","Atomic radius decreases across a period (more nuclear charge) and increases down a group.","Ionisation enthalpy increases across, decreases down; second IE > first IE always.","Electron gain enthalpy: halogens most negative; noble gases positive.","Electronegativity (Pauling) increases across, decreases down; F is the most electronegative."],formulas:[{name:"Trend rule",formula:"Size/IE/EN: ↓ across period (nuclear charge), ↑ down group (shells)"}],glossary:[{term:"Ionisation enthalpy",def:"Energy to remove the most loosely bound electron.",hindi:"आयनन एन्थैल्पी"},{term:"Electronegativity",def:"Tendency of an atom to attract shared electrons.",hindi:"विद्युत ऋणात्मकता"}],mistakes:["Saying IE increases down a group — it decreases because size grows.","Forgetting noble gases have positive electron gain enthalpy (energy must be supplied)."],pyqs:[{q:"Which element has the highest electronegativity?",options:["Fluorine","Chlorine","Oxygen","Nitrogen"],answer:0,explanation:"F is the most electronegative element (4.0 on Pauling scale)."},{q:"Atomic size across a period:",options:["decreases","increases","stays constant","first increases then decreases"],answer:0,explanation:"Increasing nuclear charge pulls electrons closer."}],tip:"Anomalies worth remembering: O vs N electron gain enthalpy, and IE₂ of Mg vs Al patterns."},"chemistry:chemistry-c4":{summary:"Chemical Bonding and Molecular Structure covers ionic and covalent bonds, VSEPR, hybridisation, MOT and hydrogen bonding.",keyPoints:["Ionic bond: complete transfer (NaCl); covalent: sharing (H₂, Cl₂); bond polarity from electronegativity difference.","Octet rule exceptions: BeCl₂, BF₃ (incomplete), PCl₅, SF₆ (expanded).","VSEPR: lone pairs repel more than bond pairs; shapes — linear (2), trigonal planar (3), tetrahedral (4), bent, pyramidal.","Hybridisation: sp (linear), sp² (trigonal planar), sp³ (tetrahedral); determines geometry.","MOT: bonding MO lower energy than antibonding; bond order = (Nb − Na)/2; O₂ is paramagnetic with BO = 2."],formulas:[{name:"Bond order (MOT)",formula:"BO = (Nb − Na)/2"}],glossary:[{term:"Hybridisation",def:"Mixing of atomic orbitals to form equivalent hybrid orbitals.",hindi:"संकरण"},{term:"VSEPR theory",def:"Electron pairs arrange to minimise repulsion, fixing shape.",hindi:"VSEPR सिद्धांत"},{term:"Hydrogen bond",def:"Attraction between H and electronegative atoms (F, O, N).",hindi:"हाइड्रोजन बंध"}],mistakes:["Counting bond pairs for geometry but ignoring lone pairs — lone pairs reshape the molecule.","Saying all bonds in a molecule are equally strong — bond order varies (e.g. benzene)."],pyqs:[{q:"The shape of NH₃ is:",options:["pyramidal","planar","linear","tetrahedral"],answer:0,explanation:"One lone pair on N distorts tetrahedral to pyramidal."},{q:"The bond order of O₂ molecule is:",options:["2","1","2.5","3"],answer:0,explanation:"O₂: (10 − 6)/2 = 2, with unpaired electrons (paramagnetic)."}],tip:"Hybridisation ↔ geometry ↔ bond angle tables are the single best revision sheet in this chapter."},"chemistry:chemistry-c5":{summary:"Thermodynamics applies energy accounting to chemistry — enthalpy, Hess's law, spontaneity and Gibbs energy.",keyPoints:["First law: ΔU = q + w (chemistry sign convention: w positive when work done ON the system).","Enthalpy H = U + PV; ΔH = ΔU + Δn_g RT; exothermic ΔH < 0.","Hess's law: ΔH of a reaction is path-independent — add steps' enthalpies.","Standard enthalpies: formation, combustion, neutralisation (−57 kJ/mol), bond enthalpy.","Spontaneity: ΔG = ΔH − TΔS < 0; ΔG = −nFE and ΔG = −RT lnK."],formulas:[{name:"Enthalpy relation",formula:"ΔH = ΔU + Δn_g RT"},{name:"Gibbs energy",formula:"ΔG = ΔH − TΔS"},{name:"Equilibrium link",formula:"ΔG° = −RT lnK"}],glossary:[{term:"Enthalpy",def:"Heat content at constant pressure.",hindi:"एन्थैल्पी"},{term:"Entropy",def:"Degree of disorder of a system.",hindi:"एन्ट्रॉपी"},{term:"Spontaneous process",def:"Process that occurs without external driving force.",hindi:"स्वतः प्रवर्तित प्रक्रम"}],mistakes:["Mixing the physics (ΔQ = ΔU + ΔW) and chemistry (ΔU = q + w) sign conventions.","Forgetting Δn_g counts only gaseous species in ΔH = ΔU + Δn_g RT."],pyqs:[{q:"For a spontaneous reaction at all temperatures:",options:["ΔH < 0, ΔS > 0","ΔH > 0, ΔS < 0","ΔH < 0, ΔS < 0","ΔH > 0, ΔS > 0"],answer:0,explanation:"ΔG = ΔH − TΔS is negative at every T only when ΔH < 0 and ΔS > 0."},{q:"The enthalpy of neutralisation of a strong acid by a strong base is about:",options:["−57 kJ/mol","−13.6 kJ/mol","+57 kJ/mol","−285 kJ/mol"],answer:0,explanation:"H⁺ + OH⁻ → H₂O releases ≈ 57 kJ/mol."}],tip:"ΔG sign questions are decided by the ΔH/ΔS temperature table — draw it once, use it everywhere."},"chemistry:chemistry-c6":{summary:"Equilibrium covers chemical equilibrium (Kp, Kc, Le Chatelier) and ionic equilibrium (pH, buffers, solubility product).",keyPoints:["Law of mass action: Kc = [products]/[reactants] at equilibrium; Kp = Kc(RT)^Δn.","Le Chatelier: a change in concentration, pressure or temperature shifts equilibrium to oppose it; catalysts don't shift it.","pH = −log[H⁺]; Kw = 10⁻¹⁴ at 25 °C; strong vs weak acids.","Buffers resist pH change: Henderson-Hasselbalch pH = pKa + log([salt]/[acid]).","Solubility product Ksp: for AgCl, Ksp = [Ag⁺][Cl⁻]; precipitation when ionic product > Ksp."],formulas:[{name:"Kp/Kc relation",formula:"Kp = Kc(RT)^Δn"},{name:"pH",formula:"pH = −log[H⁺], pH + pOH = 14"},{name:"Buffer (acidic)",formula:"pH = pKa + log([salt]/[acid])"}],glossary:[{term:"Equilibrium constant",def:"Ratio of product to reactant concentrations at equilibrium.",hindi:"साम्य स्थिरांक"},{term:"Buffer",def:"Solution resisting pH change on adding acid/base.",hindi:"बफर"},{term:"Solubility product",def:"Ksp — product of ion concentrations in a saturated solution.",hindi:"विलेयता गुणनफल"}],mistakes:["Ignoring Δn in Kp = Kc(RT)^Δn (Δn counts only gases).","Using [H⁺] = √(Ka·C) for strong acids — it applies to weak acids."],pyqs:[{q:"pH of 0.01 M HCl is:",options:["2","1","12","0.01"],answer:0,explanation:"Strong acid: [H⁺] = 0.01 M, pH = 2."},{q:"Kp = Kc for a reaction when:",options:["Δn = 0","Δn = 1","Δn = 2","Δn = −1"],answer:0,explanation:"Kp = Kc(RT)^0 = Kc when the gas mole change is zero."}],tip:"Buffer questions are formula-substitution — identify acid/salt pairs first."},"chemistry:chemistry-c7":{summary:"Redox Reactions deals with oxidation numbers, balancing redox equations and electrochemical applications.",keyPoints:["Oxidation number rules: elemental form 0; O usually −2 (peroxides −1); H +1 (hydrides −1); sum = charge of species.","Oxidising agents gain electrons (get reduced); reducing agents lose electrons.","Balancing in acidic medium: add H₂O for O, H⁺ for H, electrons for charge; in basic medium add OH⁻.","Redox disproportionation: same species both oxidised and reduced (e.g. H₂O₂, Cl₂ in base).","Electrochemistry link: oxidation at anode, reduction at cathode."],formulas:[{name:"Oxidation number",formula:"Σ(ON × atoms) = charge of species"}],glossary:[{term:"Redox reaction",def:"Reaction with simultaneous oxidation and reduction.",hindi:"रेडॉक्स अभिक्रिया"},{term:"Oxidising agent",def:"Species that oxidises others while itself getting reduced.",hindi:"ऑक्सीकारक"}],mistakes:["Assigning O = −2 in peroxides (H₂O₂ → −1 each).","Losing electrons in balancing — charge must balance along with atoms."],pyqs:[{q:"The oxidation number of Mn in KMnO₄ is:",options:["+7","+5","+2","+6"],answer:0,explanation:"+1 + x + 4(−2) = 0 ⇒ x = +7."},{q:"In the reaction 2H₂S + SO₂ → 3S + 2H₂O, sulphur is:",options:["both oxidised and reduced","only oxidised","only reduced","unchanged"],answer:0,explanation:"H₂S's S(−2) → S(0) oxidised; SO₂'s S(+4) → S(0) reduced — disproportionation."}],tip:"Practise oxidation numbers of Cr, Mn, N in common species — the most repeated MCQs."},"chemistry:chemistry-c8":{summary:"Organic Chemistry Basics covers nomenclature, isomerism, electronic effects, reaction intermediates and purification.",keyPoints:["IUPAC: longest chain, lowest locants, alphabetical prefixes, functional group priority.","Inductive effect (σ, through bonds), resonance (π, delocalisation), hyperconjugation (σ→π, needs α-H).","Stability order: carbocations 3° > 2° > 1° > methyl; free radicals and carbanions follow the reverse logic.","Isomerism: structural (chain, position, functional, metamerism, tautomerism) and stereoisomerism (geometrical, optical).","Purification: crystallisation, distillation, chromatography; detection via Lassaigne's test."],formulas:[{name:"Carbocation stability",formula:"3° > 2° > 1° > CH₃⁺"}],glossary:[{term:"Resonance",def:"Delocalisation of π electrons across a molecule.",hindi:"अनुनाद"},{term:"Inductive effect",def:"Permanent electron shift along σ bonds due to electronegativity.",hindi:"प्रेरण प्रभाव"},{term:"Hyperconjugation",def:"σ(C–H) electrons delocalising into an adjacent p-orbital/π system.",hindi:"अतिसंयुग्मन"}],mistakes:["Numbering the chain to give the functional group the lowest locant BEFORE branches.","Confusing resonance (needs π) with inductive (σ) effects in acidity questions."],pyqs:[{q:"The most stable carbocation is:",options:["tertiary","secondary","primary","methyl"],answer:0,explanation:"More alkyl groups stabilise the positive charge by hyperconjugation + inductive effect."},{q:"Which effect requires an α-hydrogen?",options:["Hyperconjugation","Inductive effect","Resonance","Electromeric effect"],answer:0,explanation:"Hyperconjugation involves σ(C–H) electrons from an α-C–H bond."}],tip:"Acidity/basicity questions almost always reduce to: stabilise the conjugate base."},"chemistry:chemistry-c9":{summary:"Hydrocarbons covers alkanes, alkenes, alkynes, benzene and aromaticity.",keyPoints:["Alkanes: free-radical halogenation, cracking, Wurtz, Kolbe; reactivity F₂ > Cl₂ > Br₂ > I₂.","Alkenes: electrophilic addition (Markovnikov), ozonolysis, hydrogenation; cis/trans isomerism.","Alkynes: acidic H (form acetylides), addition of 2 equivalents, Sandmeyer-like coupling.","Benzene: aromatic (Hückel 4n+2 π electrons, planar, conjugated); electrophilic substitution (nitration, halogenation, Friedel-Crafts).","Directing effects: −NO₂, −CN meta-directing deactivators; −CH₃, −OH ortho/para directors."],formulas:[{name:"Hückel rule",formula:"Aromatic if (4n+2) π electrons in a planar ring"}],glossary:[{term:"Markovnikov's rule",def:"H adds to the carbon with more H; carbocation forms at the more substituted carbon.",hindi:"मार्कोवनिकोव नियम"},{term:"Aromaticity",def:"Special stability from cyclic, planar, conjugated 4n+2 π electron systems.",hindi:"ऐरोमैटिकता"}],mistakes:["Adding Br₂ to an alkene and expecting substitution — alkenes do addition.","Calling cyclooctatetraene aromatic — it's non-planar, so 4n rule applies but it's antiaromatic/non-aromatic."],pyqs:[{q:"Propene reacts with HBr mainly to give:",options:["2-bromopropane","1-bromopropane","1,2-dibromopropane","propanol"],answer:0,explanation:"Markovnikov addition puts Br on the more substituted carbon (2°)."},{q:"Benzene undergoes mainly:",options:["electrophilic substitution","addition","free radical substitution","elimination"],answer:0,explanation:"Aromatic stability favours substitution over addition."}],tip:"Markovnikov + carbocation stability together answer half the alkene PYQs."},"chemistry:chemistry-c10":{summary:"Solutions covers concentration, Raoult's law, colligative properties, osmosis and abnormal molar masses.",keyPoints:["Raoult's law: P = P°x; ideal solutions obey it at all concentrations (ΔH_mix = 0, ΔV = 0).","Colligative properties depend on particle NUMBER: ΔTf, ΔTb, osmotic pressure π = CRT.","Relative lowering of vapour pressure = mole fraction of solute.","Elevation of boiling point ΔTb = Kb·m; depression of freezing point ΔTf = Kf·m.","van't Hoff factor i: dissociation i > 1, association i < 1; abnormal molar mass = normal/i."],formulas:[{name:"Raoult's law",formula:"P₁ = x₁P°₁"},{name:"Boiling point elevation",formula:"ΔTb = Kb·m"},{name:"Osmotic pressure",formula:"π = iCRT"},{name:"van't Hoff factor",formula:"i = observed colligative / expected"}],glossary:[{term:"Colligative property",def:"Depends only on the number of solute particles.",hindi:"अनुसंपार्श्विक गुण"},{term:"Osmosis",def:"Solvent flow through a semipermeable membrane toward higher solute concentration.",hindi:"परासरण"}],mistakes:["Using grams instead of moles in molality — m is per kg solvent.","Forgetting i for electrolytes: NaCl gives i ≈ 2, CaCl₂ i ≈ 3."],pyqs:[{q:"Which colligative property is best for molar mass of polymers?",options:["Osmotic pressure","Boiling point elevation","Freezing point depression","Vapour pressure lowering"],answer:0,explanation:"Osmotic pressure is measurable even at very low concentrations (large molecules)."},{q:"For 0.1 M NaCl solution at 25 °C (i = 2), the osmotic pressure is:",options:["2 × 0.1 × RT","0.1 × RT","0.2 × 0.1 × RT","RT"],answer:0,explanation:"π = iCRT = 2 × 0.1 × RT."}],tip:"Spot i quickly: non-electrolytes i = 1; count ions for salts."},"chemistry:chemistry-c11":{summary:"Electrochemistry covers conductance, electrolysis, electrode potentials, the Nernst equation, batteries and corrosion.",keyPoints:["Conductivity κ depends on ions; molar conductivity Λm = κ/C increases with dilution for weak electrolytes.","Electrolysis: Faraday's laws; m = ZIt = (M/nF)·It.","Standard electrode potential: more negative E° = stronger reductant at anode; cell EMF = E°cathode − E°anode.","Nernst equation: E = E° − (0.059/n)log Q (at 25 °C).","Batteries: dry cell (Zn anode, MnO₂ cathode), lead storage (rechargeable), fuel cells; corrosion = oxidation of metals."],formulas:[{name:"Nernst equation",formula:"E = E° − (0.059/n) log Q"},{name:"Faraday's law",formula:"m = (M·I·t)/(nF)"},{name:"Cell EMF",formula:"E°cell = E°cathode − E°anode"}],glossary:[{term:"Electrolysis",def:"Decomposition using electric current.",hindi:"विद्युत अपघटन"},{term:"Electrode potential",def:"Tendency of an electrode to lose/gain electrons.",hindi:"इलेक्ट्रोड विभव"}],mistakes:["Computing E°cell with the wrong sign — always reduce at cathode, oxidise at anode.","Forgetting n = electrons exchanged per formula unit in Faraday calculations."],pyqs:[{q:"The EMF of a cell is given by:",options:["E°cathode − E°anode","E°anode − E°cathode","E°cathode + E°anode","E°anode × E°cathode"],answer:0,explanation:"Reduction potential of cathode minus reduction potential of anode."},{q:"To deposit 1 mole of silver (n = 1) needs:",options:["1 Faraday","2 Faraday","0.5 Faraday","96500 J"],answer:0,explanation:"m = M·It/(nF); 1 mole requires 1F = 96500 C."}],tip:"Nernst: a 10× change in Q changes E by 0.059/n V — remember the 0.059 shortcut."},"chemistry:chemistry-c12":{summary:"Chemical Kinetics studies reaction rates, order, integrated rate laws, half-life, the Arrhenius equation and catalysis.",keyPoints:["Rate = change in concentration/time; instantaneous rate from the tangent slope.","Order (experimental) vs molecularity (theoretical, for elementary steps only).","Zero order: [A] falls linearly, t₁/₂ = [A]₀/2k; first order: ln[A] = −kt + ln[A]₀, t₁/₂ = 0.693/k.","Second order: 1/[A] = kt + 1/[A]₀; t₁/₂ = 1/(k[A]₀).","Arrhenius: k = Ae^(−Ea/RT); a catalyst lowers Ea, speeding the reaction without changing ΔH."],formulas:[{name:"First-order half-life",formula:"t₁/₂ = 0.693/k"},{name:"Arrhenius equation",formula:"k = Ae^(−Ea/RT)"},{name:"Zero-order half-life",formula:"t₁/₂ = [A]₀/2k"}],glossary:[{term:"Activation energy",def:"Minimum energy reactants need to form products.",hindi:"सक्रियण ऊर्जा"},{term:"Catalyst",def:"Substance that speeds a reaction by lowering Ea, unchanged at the end.",hindi:"उत्प्रेरक"}],mistakes:["Reading order from the balanced equation — order comes from experiments.","Using t₁/₂ = 0.693/k for zero-order reactions."],pyqs:[{q:"The half-life of a first-order reaction with k = 0.0693 min⁻¹ is:",options:["10 min","6.93 min","0.693 min","100 min"],answer:0,explanation:"t₁/₂ = 0.693/0.0693 = 10 min."},{q:"A catalyst works by:",options:["lowering activation energy","increasing activation energy","changing ΔH","changing equilibrium constant"],answer:0,explanation:"Catalysts provide an alternative path with lower Ea."}],tip:"t₁/₂ of first-order reactions is concentration-independent — a favourite assertion."},"chemistry:chemistry-c13":{summary:"The d- and f-Block Elements covers transition metals, their properties, lanthanoids and actinoids.",keyPoints:["d-block: partially filled d subshell; typical properties — variable oxidation states, coloured ions, catalytic activity, complex formation.","Trends: atomic size decreases slowly, then rises at the end; ionisation enthalpy rises steadily.","Mn shows the maximum oxidation states (+2 to +7); Cu⁺, Zn²⁺, Sc³⁺ are colourless (d⁰/d¹⁰).","K₂Cr₂O₇ (orange) and KMnO₄ (purple) are powerful oxidising agents in acidic medium.","f-block: lanthanoids (4f, similar chemistry, lanthanoid contraction) and actinoids (5f, radioactive)."],formulas:[{name:"Colour rule",formula:"Coloured ions need unpaired d-electrons (d¹–d⁹)"}],glossary:[{term:"Transition element",def:"Element with partially filled d orbital in its ion/common state.",hindi:"संक्रमण तत्व"},{term:"Lanthanoid contraction",def:"Steady size decrease across lanthanoids due to poor 4f shielding.",hindi:"लैंथेनॉइड संकुचन"}],mistakes:["Including Zn, Cd, Hg as transition metals in colour questions — they are d¹⁰ and colourless.","Saying all d-block ions are coloured — d⁰ and d¹⁰ are not."],pyqs:[{q:"Which ion is colourless in aqueous solution?",options:["Zn²⁺","Cu²⁺","Fe³⁺","Mn²⁺"],answer:0,explanation:"Zn²⁺ is d¹⁰ — no d–d transitions, so colourless."},{q:"KMnO₄ acts as an oxidising agent in acidic medium, changing Mn from +7 to:",options:["+2","+4","+6","+7"],answer:0,explanation:"In acid, MnO₄⁻ reduces to Mn²⁺."}],tip:"For colour/paramagnetism, count unpaired d-electrons — that single skill answers many MCQs."},"chemistry:chemistry-c14":{summary:"Coordination Compounds covers Werner's theory, nomenclature, isomerism, VBT, CFT and applications.",keyPoints:["Coordination entity: central metal + ligands; coordination number = number of donor atoms attached.","Werner's theory: primary valency (ionisable) + secondary valency (fixed, directional).","Nomenclature: ligands alphabetically, 'ate' for anionic complexes, oxidation state in Roman numerals.","Isomerism: ionisation, hydrate, linkage, geometrical (cis/trans), optical (d/l).","CFT: ligand field splits d-orbitals; strong field (CN⁻, CO) → low spin; weak field (H₂O, F⁻) → high spin."],formulas:[{name:"Crystal field stabilisation",formula:"Δ₀ > pairing energy ⇒ low spin; Δ₀ < pairing energy ⇒ high spin"}],glossary:[{term:"Ligand",def:"Ion/molecule donating electron pairs to the central metal.",hindi:"लिगैंड"},{term:"Coordination number",def:"Number of ligand donor atoms bonded to the metal.",hindi:"उपसहसंयोजन संख्या"},{term:"Chelate",def:"Ring formed when a multidentate ligand binds a metal.",hindi:"कीलेट"}],mistakes:["Writing the oxidation state of a complex without summing ligand charges correctly.","Forgetting that NH₃ is neutral in charge sums (Co³⁺ in [Co(NH₃)₆]³⁺)."],pyqs:[{q:"In [Co(NH₃)₆]Cl₃, the oxidation state of Co is:",options:["+3","+2","+1","+6"],answer:0,explanation:"x + 0 − 3 = 0 ⇒ x = +3."},{q:"Which ligand is bidentate?",options:["Ethylenediamine (en)","H₂O","NH₃","Cl⁻"],answer:0,explanation:"en has two donor N atoms, forming chelate rings."}],tip:"Learn the spectrochemical series order — it decides low vs high spin in most CFT questions."},"chemistry:chemistry-c15":{summary:"Haloalkanes and Haloarenes covers preparation and reactions — SN1/SN2, elimination, Grignard reagents and haloarene chemistry.",keyPoints:["SN2: one step, backside attack, inversion, favoured by primary halides + strong nucleophile.","SN1: two steps via carbocation, racemisation, favoured by tertiary halides + polar protic solvent.","Elimination (E1/E2) competes with substitution — strong bulky base favours elimination.","Grignard reagents RMgX form alcohols with carbonyls, hydrocarbons with water.","Haloarenes: less reactive in substitution (resonance + no backside attack); nucleophilic substitution needs drastic conditions."],formulas:[{name:"Reactivity (SN2)",formula:"CH₃X > 1° > 2° > 3°"},{name:"Reactivity (SN1)",formula:"3° > 2° > 1° > CH₃X"}],glossary:[{term:"SN1 reaction",def:"Unimolecular nucleophilic substitution via carbocation.",hindi:"SN1 अभिक्रिया"},{term:"Grignard reagent",def:"RMgX — organometallic with nucleophilic carbon.",hindi:"ग्रिग्नार्ड अभिकर्मक"}],mistakes:["Using SN2 order for tertiary halides — they prefer SN1 (steric hindrance).","Adding water to Grignard and expecting an alcohol — you get the hydrocarbon RH."],pyqs:[{q:"Which halide reacts fastest by SN2?",options:["CH₃Br","(CH₃)₃CBr","(CH₃)₂CHBr","C₆H₅Br"],answer:0,explanation:"SN2 needs a backside attack — least hindered methyl is fastest."},{q:"Tertiary butyl halide mainly undergoes:",options:["SN1","SN2","neither","free radical substitution"],answer:0,explanation:"Stable tertiary carbocation makes SN1 dominant."}],tip:"Decide SN1 vs SN2 in three steps: substrate (1°/2°/3°), nucleophile strength, solvent polarity."},"chemistry:chemistry-c16":{summary:"Alcohols, Phenols and Ethers covers their preparation, reactions, acidity and distinction tests.",keyPoints:["Alcohols: from alkenes (hydration), carbonyls (reduction, Grignard), haloalkanes (hydrolysis).","Reactions: esterification, oxidation (1°→aldehyde→acid, 2°→ketone), dehydration to alkenes.","Phenols are more acidic than alcohols (phenoxide resonance); electron-withdrawing groups increase acidity.","Ethers: Williamson synthesis (alkoxide + alkyl halide); cleavage by HI.","Distinction tests: Lucas (3° immediate), Iodoform (CH₃CH(OH)– group), FeCl₃ (phenols → violet)."],formulas:[{name:"Lucas test",formula:"3° alcohol: immediate turbidity; 2°: few minutes; 1°: no reaction at room temp"}],glossary:[{term:"Phenoxide ion",def:"Conjugate base of phenol, stabilised by resonance.",hindi:"फीनॉक्साइड आयन"},{term:"Williamson synthesis",def:"Ether formation from alkoxide and alkyl halide.",hindi:"विलियमसन संश्लेषण"}],mistakes:["Saying alcohol is more acidic than phenol — it is the reverse.","Using Lucas reagent on phenols — Lucas is for alcohols only."],pyqs:[{q:"Which is most acidic?",options:["Phenol","Ethanol","Methanol","Water"],answer:0,explanation:"Phenoxide resonance makes phenol more acidic than alcohols."},{q:"An alcohol giving an immediate turbidity with Lucas reagent is:",options:["tertiary","primary","secondary","methyl"],answer:0,explanation:"3° alcohols form stable carbocations instantly."}],tip:"Acidity of phenols follows substituent effects: NO₂ raises acidity, CH₃ lowers it."},"chemistry:chemistry-c17":{summary:"Aldehydes, Ketones and Carboxylic Acids covers carbonyl preparation, nucleophilic addition, oxidations, named reactions and acid chemistry.",keyPoints:["Carbonyl carbon is electrophilic; nucleophiles add — HCN, NaHSO₃, alcohols (acetals), Grignard.","Aldehydes are more reactive than ketones (less steric + electronic hindrance).","Oxidation: aldehydes → acids (Tollen's silver mirror, Fehling's); ketones resist mild oxidants.","Named reactions: Aldol (α-H + base), Cannizzaro (no α-H + conc. base), Clemmensen/Wolff-Kishner (C=O → CH₂).","Carboxylic acids: acidic (resonance-stabilised carboxylate), esterification, decarboxylation, Hell-Volhard-Zelinsky."],formulas:[{name:"Aldol reaction",formula:"2 aldehydes/ketones with α-H + dil. base → β-hydroxy carbonyl"}],glossary:[{term:"Nucleophilic addition",def:"Addition to C=O where the nucleophile attacks the carbonyl carbon.",hindi:"नाभिकस्नेही योग"},{term:"Cannizzaro reaction",def:"Aldehyde without α-H disproportionates in conc. base to alcohol + acid.",hindi:"कैनिज़ारो अभिक्रिया"}],mistakes:["Applying Aldol to aldehydes without α-H (use Cannizzaro there).","Saying ketones give Tollen's test — only aldehydes (and α-hydroxy ketones) do."],pyqs:[{q:"Which gives a silver mirror with Tollen's reagent?",options:["Acetaldehyde","Acetone","Acetophenone","Ethyl acetate"],answer:0,explanation:"Aldehydes are oxidised by Tollen's reagent; ketones are not."},{q:"Formaldehyde (no α-H) with conc. NaOH gives:",options:["methanol + formic acid","aldol","acetic acid","ethane"],answer:0,explanation:"Cannizzaro disproportionation: CH₃OH + HCOONa."}],tip:"When you see 'no α-hydrogen + concentrated base', think Cannizzaro instantly."},"chemistry:chemistry-c18":{summary:"Amines covers their classification, preparation, basicity and diazonium chemistry.",keyPoints:["Amines: 1°, 2°, 3° by number of alkyl/aryl groups on N; RNH₂ are weak bases (lone pair on N).","Preparation: Gabriel phthalimide (1° only), Hofmann bromamide degradation (amide → 1° amine), reduction of nitriles.","Basicity in gas phase: 3° > 2° > 1° > NH₃; in water: 2° > 1° > 3° > NH₃ (solvation effects).","Aniline is weaker than aliphatic amines (resonance delocalises the lone pair).","Diazonium salts (ArN₂⁺) from aniline + NaNO₂/HCl at 0–5 °C: Sandmeyer, Gatterman, coupling, azo dyes."],formulas:[{name:"Hofmann degradation",formula:"RCONH₂ + Br₂ + 4NaOH → RNH₂ + Na₂CO₃ + 2NaBr + 2H₂O"}],glossary:[{term:"Diazonium salt",def:"ArN₂⁺X⁻, versatile intermediate made at low temperature.",hindi:"डाइएज़ोनियम लवण"},{term:"Gabriel synthesis",def:"Clean route to primary amines via phthalimide.",hindi:"गैब्रीएल संश्लेषण"}],mistakes:["Saying 3° amines are most basic in water — solvation flips the order.","Forgetting diazotisation needs 0–5 °C (above that, phenol forms)."],pyqs:[{q:"In aqueous solution, the most basic amine is:",options:["2° amine","1° amine","3° amine","NH₃"],answer:0,explanation:"Alkyl donation + better solvation of 2° ammonium ions win over 3° steric/less solvation."},{q:"Diazonium salts are formed at:",options:["0–5 °C","room temperature","100 °C","reflux"],answer:0,explanation:"Low temperature prevents phenol formation from the diazonium salt."}],tip:"Aniline + NaNO₂ + HCl cold = diazonium salt — the launch pad for a dozen reactions."},"chemistry:chemistry-c19":{summary:"Biomolecules covers carbohydrates, proteins, enzymes, vitamins, nucleic acids and lipids.",keyPoints:["Carbohydrates: monosaccharides (glucose, fructose), disaccharides (sucrose, maltose, lactose), polysaccharides (starch, cellulose, glycogen).","Glucose: C₆H₁₂O₆, open chain (CHO) + cyclic (pyranose); reducing sugar (gives Tollen's/Fehling's).","Proteins: amino acids joined by peptide bonds; structure levels primary → quaternary; denaturation unfolds them.","Enzymes are protein catalysts with active sites; vitamins are essential organic micronutrients (B, C water-soluble; A, D, E, K fat-soluble).","Nucleic acids: DNA (double helix, deoxyribose, A-T/G-C) and RNA (single, ribose, U instead of T)."],formulas:[{name:"Reducing sugar test",formula:"Glucose/fructose/maltose/lactose reduce Tollen's & Fehling's; sucrose does not"}],glossary:[{term:"Peptide bond",def:"Amide link between amino acids (−CO–NH−).",hindi:"पेप्टाइड बंध"},{term:"Denaturation",def:"Loss of a protein's native structure and function.",hindi:"विकृतीकरण"}],mistakes:["Calling sucrose a reducing sugar — it is non-reducing (both anomeric carbons linked).","Saying DNA has uracil — that's RNA; DNA has thymine."],pyqs:[{q:"Which sugar is non-reducing?",options:["Sucrose","Glucose","Maltose","Lactose"],answer:0,explanation:"In sucrose both anomeric carbons are involved in the glycosidic bond."},{q:"The monomer of proteins is:",options:["amino acid","glucose","nucleotide","fatty acid"],answer:0,explanation:"Proteins are polymers of α-amino acids joined by peptide bonds."}],tip:"For carbohydrate MCQs, check reducing/non-reducing and the glycosidic linkage — that's 80% of it."}},d={"biology:biology-c1":{summary:"The Living World introduces biodiversity, taxonomy, nomenclature and taxonomic aids — the vocabulary chapter of biology.",keyPoints:["Living things: growth, reproduction, metabolism (defining feature), cellular organisation, consciousness.","Binomial nomenclature (Linnaeus): Genus + species, italicised, genus capitalised.","Taxonomic hierarchy: Species < Genus < Family < Order < Class < Phylum < Kingdom < Domain.","Taxonomic aids: herbarium, botanical/museums, zoological parks, keys, manuals, monographs.","Systematics = classification + evolutionary relationships."],glossary:[{term:"Taxonomy",def:"Science of identification, naming and classification of organisms.",hindi:"वर्गिकी"},{term:"Species",def:"Basic unit of classification; interbreeding natural populations.",hindi:"जाति"}],mistakes:["Writing the binomial without italics or with both words capitalised.","Confusing 'growth' as a defining feature — non-living things (crystals) also grow."],pyqs:[{q:"The most basic unit of classification is:",options:["Species","Genus","Family","Order"],answer:0,explanation:"Species is the lowest and basic unit in the hierarchy."},{q:"Binomial nomenclature was given by:",options:["Linnaeus","Darwin","Mendel","Haeckel"],answer:0,explanation:"Carolus Linnaeus introduced the binomial system."}],tip:"Metabolism is the defining feature of life — NCERT says it explicitly."},"biology:biology-c2":{summary:"Biological Classification compares the five kingdoms — Monera, Protista, Fungi, Plantae, Animalia — plus viruses and lichens.",keyPoints:["R.H. Whittaker's five kingdoms: Monera, Protista, Fungi, Plantae, Animalia.","Monera: prokaryotes, no membrane-bound organelles; eubacteria, archaebacteria (extremophiles), cyanobacteria (BGA fix nitrogen).","Protista: unicellular eukaryotes — diatoms (silica shells), slime moulds, protozoans.","Fungi: saprophytes/parasites, chitin cell walls; zygomycetes, ascomycetes, basidiomycetes, deuteromycetes.","Viruses are obligate parasites (no cell), viroids are naked RNA, lichens = algae + fungi (symbiosis, pollution indicators)."],glossary:[{term:"Archaebacteria",def:"Ancient prokaryotes thriving in extreme habitats (halophiles, thermoacidophiles).",hindi:"आर्कीबैक्टीरिया"},{term:"Lichens",def:"Symbiotic association of algae and fungi; sensitive pollution indicators.",hindi:"लाइकेन"}],mistakes:["Putting cyanobacteria in Protista — they are Monera (prokaryotes).","Calling viruses living — they are inert outside a host cell."],pyqs:[{q:"Which kingdom includes organisms with chitin cell walls?",options:["Fungi","Monera","Protista","Plantae"],answer:0,explanation:"Fungal cell walls contain chitin."},{q:"Lichens indicate:",options:["air pollution levels","soil fertility","water purity","temperature"],answer:0,explanation:"Lichens die with SO₂ pollution — sensitive bioindicators."}],tip:"Match organisms to kingdoms via three clues: cell type, cell wall, nutrition."},"biology:biology-c3":{summary:"Plant Kingdom covers algae, bryophytes, pteridophytes, gymnosperms and angiosperms with their life cycles.",keyPoints:["Algae: chlorophyll-bearing, thallus body; green (chlorophyceae), brown (phaeophyceae), red (rhodophyceae).","Bryophytes: amphibians of the plant world; liverworts and mosses; gametophyte dominant, need water for fertilisation.","Pteridophytes: first vascular plants; sporophyte dominant; horsetails, ferns.","Gymnosperms: naked seeds, no fruit; cycas, pines; heterosporous.","Angiosperms: covered seeds, flowers, double fertilisation; haplo-diplontic life cycle."],glossary:[{term:"Gametophyte",def:"Haploid, gamete-producing phase of a plant life cycle.",hindi:"युग्मकोद्भिद्"},{term:"Heterospory",def:"Production of two kinds of spores — micro and mega.",hindi:"विषमबीजाणुता"}],mistakes:["Saying bryophytes have vascular tissue — they lack true xylem/phloem.","Calling pteridophytes gametophyte-dominant — sporophyte dominates."],pyqs:[{q:"Which group is called the amphibians of the plant kingdom?",options:["Bryophytes","Algae","Pteridophytes","Gymnosperms"],answer:0,explanation:"Bryophytes live on land but need water for reproduction."},{q:"Gymnosperms differ from angiosperms in having:",options:["naked seeds","flowers","double fertilisation","fruits"],answer:0,explanation:"Gymnosperm seeds are not enclosed in fruits."}],tip:"For life-cycle questions: bryophytes = gametophyte dominant; pteridophytes onward = sporophyte dominant."},"biology:biology-c4":{summary:"Animal Kingdom classifies animals from Porifera to Chordata with their diagnostic features.",keyPoints:["Basis of classification: symmetry, germ layers, coelom, segmentation, notochord.","Porifera: sponges, cellular level, water canal system (Sycon, Euspongia).","Cnidaria: diploblastic, cnidoblasts, radial symmetry (Hydra, jellyfish, corals).","Platyhelminthes: flatworms, triploblastic, acoelomate (Planaria, liver fluke, tapeworm).","Chordata: notochord, dorsal hollow nerve cord, pharyngeal gill slits — vertebrates are one subphylum."],glossary:[{term:"Coelom",def:"Body cavity lined by mesoderm.",hindi:"प्रगुहा"},{term:"Notochord",def:"Rod-like skeletal structure present at some stage in chordates.",hindi:"नोटोकॉर्ड"}],mistakes:["Calling cnidarians triploblastic — they are diploblastic.","Putting starfish in Mollusca — echinoderms have water vascular systems."],pyqs:[{q:"Which phylum has a water canal system?",options:["Porifera","Cnidaria","Echinodermata","Annelida"],answer:0,explanation:"Sponges filter feed through a water canal system."},{q:"The presence of a notochord defines:",options:["Chordata","Echinodermata","Annelida","Arthropoda"],answer:0,explanation:"Notochord is the diagnostic feature of chordates."}],tip:"Learn one 'standard example' per phylum — NEET asks feature↔example matches."},"biology:biology-c5":{summary:"Morphology of Flowering Plants covers root, stem, leaf, inflorescence, flower, fruit, seed and key families.",keyPoints:["Roots: tap (dicots) vs fibrous (monocots); modifications — storage (carrot), prop (banyan), pneumatophores (mangroves).","Stem: node, internode, axillary bud; modifications — rhizome (ginger), tuber (potato), bulb (onion).","Leaf: lamina, petiole; venation parallel (monocots) vs reticulate (dicots); phyllotaxy.","Flower: calyx, corolla, androecium, gynoecium; placentation types.","Families: Fabaceae (pea), Solanaceae (potato, tomato), Liliaceae (lily) — floral formula & diagram."],glossary:[{term:"Inflorescence",def:"Arrangement of flowers on the floral axis (racemose vs cymose).",hindi:"पुष्पक्रम"},{term:"Placentation",def:"Arrangement of ovules in the ovary.",hindi:"बीजांडासन"}],mistakes:["Calling potato a root — it is a modified underground stem (tuber) with eyes (buds).","Matching pea to Solanaceae — pea is Fabaceae."],pyqs:[{q:"The eye of a potato is:",options:["an axillary bud","a root","a leaf","a flower"],answer:0,explanation:"Potato tuber is a stem; its eyes are axillary buds."},{q:"Reticulate venation is typical of:",options:["dicots","monocots","bryophytes","gymnosperms only"],answer:0,explanation:"Dicot leaves show reticulate venation."}],tip:"Modification questions: find the 'eyes/nodes' to identify stems vs roots."},"biology:biology-c6":{summary:"Anatomy of Flowering Plants examines tissues, tissue systems and the internal structure of stems, roots and leaves.",keyPoints:["Meristems: apical, intercalary, lateral (cambium) — sites of growth.","Simple tissues: parenchyma, collenchyma, sclerenchyma; complex: xylem & phloem.","Vascular bundle types: radial, conjoint, open (dicots, with cambium), closed (monocots).","Monocot vs dicot: scattered vs ring vascular bundles; polyarch vs diarch roots.","Secondary growth: vascular + cork cambium produce wood and bark (dicots & gymnosperms)."],glossary:[{term:"Meristem",def:"Tissue with continuously dividing cells.",hindi:"विभज्योतक"},{term:"Secondary growth",def:"Increase in girth by lateral meristems.",hindi:"द्वितीयक वृद्धि"}],mistakes:["Saying monocots show secondary growth — normally they do not (no cambium).","Calling xylem a simple tissue — it is complex (tracheids, vessels, fibres, parenchyma)."],pyqs:[{q:"Closed vascular bundles are found in:",options:["monocots","dicots","gymnosperms","ferns"],answer:0,explanation:"Monocot bundles lack cambium, so they are closed."},{q:"Secondary growth occurs due to:",options:["lateral meristems","apical meristems","intercalary meristems","only xylem"],answer:0,explanation:"Vascular and cork cambium (lateral meristems) add girth."}],tip:"Draw the dicot T.S. once — bundle ring + open bundles is the NEET favourite."},"biology:biology-c7":{summary:"Structural Organisation in Animals covers tissues plus the anatomy of earthworm, cockroach and frog.",keyPoints:["Animal tissues: epithelial, connective, muscular, neural.","Earthworm: hermaphrodite; clitellum (segments 14–16); nephridia excrete; typhlosole increases absorption.","Cockroach: 13 segments, open circulatory system with haemolymph, malpighian tubules excrete; dioecious.","Frog: skin respiration, three-chambered heart, ureotelic; external fertilisation in water.","Epithelial types: squamous, cuboidal, columnar, ciliated, glandular, transitional."],glossary:[{term:"Clitellum",def:"Glandular band of earthworm forming cocoons.",hindi:"क्लाइटेलम"},{term:"Malpighian tubules",def:"Excretory organs of cockroach.",hindi:"मैल्पीघी नलिकाएँ"}],mistakes:["Saying cockroach has a closed circulatory system — it is open.","Calling frogs ureotelic AND uricotelic — they excrete urea (ureotelic)."],pyqs:[{q:"Excretory organs of cockroach are:",options:["malpighian tubules","nephridia","flame cells","kidneys"],answer:0,explanation:"Malpighian tubules remove nitrogenous waste in insects."},{q:"Earthworm is:",options:["hermaphrodite","unisexual","asexual","parthenogenetic"],answer:0,explanation:"Both male and female organs occur in the same worm."}],tip:"Earthworm/cockroach/frog — keep a one-line 'excretion, circulation, reproduction' table."},"biology:biology-c8":{summary:"Cell: The Unit of Life details the cell theory, membrane, organelles, nucleus and prokaryotic vs eukaryotic cells.",keyPoints:["Cell theory: Schleiden & Schwann; all cells from pre-existing cells (Virchow).","Fluid mosaic model: phospholipid bilayer + proteins; selectively permeable.","Endomembrane system: ER, Golgi, lysosomes, vacuoles (nucleus, mitochondria, chloroplasts excluded).","Mitochondria (powerhouse, cristae, matrix) and chloroplasts (thylakoids, grana) are semi-autonomous.","Prokaryotes lack membrane-bound organelles and a true nucleus; ribosomes 70S vs eukaryotic 80S."],glossary:[{term:"Endomembrane system",def:"Interconnected membrane organelles — ER, Golgi, lysosomes, vacuoles.",hindi:"अंत:झिल्ली तंत्र"},{term:"Semi-autonomous organelle",def:"Organelle with its own DNA & ribosomes (mitochondria, plastids).",hindi:"अर्ध-स्वायत्त अंगक"}],mistakes:["Including mitochondria in the endomembrane system — they are excluded.","Giving 80S ribosomes to bacteria — prokaryotes have 70S."],pyqs:[{q:"Which organelle is NOT part of the endomembrane system?",options:["Mitochondria","Golgi apparatus","ER","Lysosomes"],answer:0,explanation:"Mitochondria function independently of the endomembrane system."},{q:"Ribosomes of prokaryotes are:",options:["70S","80S","60S","40S"],answer:0,explanation:"Prokaryotic ribosomes are 70S (50S + 30S)."}],tip:"If a question lists organelles and asks for the odd one, check the endomembrane list first."},"biology:biology-c9":{summary:"Biomolecules separates micromolecules from macromolecules — proteins, carbohydrates, lipids, nucleic acids and metabolic pools.",keyPoints:["Micromolecules (amino acids, sugars, nucleotides, lipids) vs macromolecules (proteins, polysaccharides, nucleic acids).","Proteins: polymers of amino acids; 20 standard types; peptide bonds.","Enzymes: protein catalysts; active site; substrate-specific; enzyme activity affected by pH, temperature, inhibitors.","Carbohydrates: monosaccharides (glucose C₆H₁₂O₆), disaccharides (sucrose, maltose, lactose), polysaccharides (starch, cellulose, glycogen).","Metabolism: anabolism (build) + catabolism (break) — a living state's defining chemistry."],glossary:[{term:"Metabolic pool",def:"Collection of micromolecules inside cells used for synthesis.",hindi:"चयापचय पूल"},{term:"Active site",def:"Region of an enzyme where the substrate binds.",hindi:"सक्रिय स्थल"}],mistakes:["Classifying lipids as macromolecules — they are micromolecules (not polymers).","Saying cellulose is digestible by humans — we lack cellulase."],pyqs:[{q:"Which is a macromolecule?",options:["Protein","Glucose","Amino acid","ATP"],answer:0,explanation:"Proteins are polymers; the others are micromolecules."},{q:"Enzymes are basically:",options:["proteins","lipids","carbohydrates","nucleic acids"],answer:0,explanation:"Most enzymes are globular proteins."}],tip:"The polymer test: if it's built from repeating monomers, it's a macromolecule (lipids are the exception)."},"biology:biology-c10":{summary:"Cell Cycle and Cell Division covers interphase, mitosis and meiosis.",keyPoints:["Interphase: G1 (growth), S (DNA replication — 2C→4C), G2 (preparation); M phase is short.","Mitosis: one division, 2 identical daughter cells, somatic; prophase, metaphase, anaphase, telophase.","Metaphase: chromosomes align at the equator; anaphase: sister chromatids separate.","Meiosis: two divisions, 4 haploid cells, genetic variation via crossing over (pachytene) and independent assortment.","Meiosis I: homologous chromosomes separate (reduction); Meiosis II: sister chromatids separate (equational)."],glossary:[{term:"Crossing over",def:"Exchange of segments between homologous chromosomes in pachytene.",hindi:"पारगमन"},{term:"Chiasmata",def:"Visible points of crossing over between chromatids.",hindi:"काइज़्मेटा"}],mistakes:["Saying DNA replicates during M phase — it happens in S phase.","Calling meiosis II a reductional division — only meiosis I is."],pyqs:[{q:"DNA replication occurs in which phase?",options:["S phase","G1","G2","M phase"],answer:0,explanation:"Synthesis phase doubles the DNA content."},{q:"Crossing over occurs during:",options:["pachytene","leptotene","diplotene","metaphase I"],answer:0,explanation:"Recombination happens at pachytene of prophase I."}],tip:"Match each phase to ONE key event — that mapping answers most cell-cycle MCQs."},"biology:biology-c11":{summary:"Photosynthesis in Higher Plants covers pigments, light reactions, the Calvin cycle, C4 and CAM pathways.",keyPoints:["Chlorophyll a (blue-green, reaction centre) and b (yellow-green, accessory); carotenoids protect and harvest light.","Light reaction: PSII (water splitting, O₂ release, ATP) and PSI (NADPH); occurs in thylakoids.","Calvin cycle (C3): CO₂ fixation by RuBisCO → 3-PGA → G3P; needs ATP + NADPH from light reactions.","C4 plants (maize, sugarcane): PEP carboxylase fixes CO₂ in mesophyll → C4 acid → Calvin cycle in bundle sheath (Kranz anatomy).","Photorespiration: RuBisCO fixes O₂ instead of CO₂ — wasteful, absent in C4 (no net loss)."],glossary:[{term:"Kranz anatomy",def:"Bundle sheath cells surrounding vascular bundles in C4 plants.",hindi:"क्रांज संरचना"},{term:"Photorespiration",def:"Oxygen fixation by RuBisCO wasting energy.",hindi:"प्रकाशश्वसन"}],mistakes:["Saying O₂ is released from CO₂ — it comes from water photolysis.","Calling RuBisCO a C4 enzyme — it works in the Calvin cycle."],pyqs:[{q:"Oxygen released in photosynthesis comes from:",options:["water","CO₂","glucose","chlorophyll"],answer:0,explanation:"Water photolysis at PSII releases O₂."},{q:"Kranz anatomy is found in:",options:["C4 plants","C3 plants","CAM plants only","algae"],answer:0,explanation:"Bundle sheath chloroplasts define C4 (Kranz) anatomy."}],tip:"Remember the triad: PSII → water + ATP; PSI → NADPH; Calvin → sugar."},"biology:biology-c12":{summary:"Respiration in Plants traces glycolysis, the Krebs cycle, the electron transport chain and fermentation.",keyPoints:["Glycolysis (cytoplasm): glucose → 2 pyruvate, 2 ATP, 2 NADH; no O₂ needed.","Krebs cycle (mitochondrial matrix): acetyl-CoA → CO₂, NADH, FADH₂, 1 ATP per turn.","ETC (inner mitochondrial membrane): NADH→3 ATP, FADH₂→2 ATP; ATP synthase makes ATP.","Net aerobic: 1 glucose → ~36–38 ATP; fermentation (yeast) gives ethanol + CO₂; (muscles) lactic acid.","Respiratory quotient RQ = CO₂ released/O₂ consumed; carbohydrates ≈ 1, fats < 1, organic acids > 1."],glossary:[{term:"Glycolysis",def:"Cytosolic splitting of glucose into two pyruvate molecules.",hindi:"ग्लाइकोलिसिस"},{term:"Respiratory quotient",def:"Ratio of CO₂ produced to O₂ consumed.",hindi:"श्वसन गुणांक"}],mistakes:["Placing glycolysis in mitochondria — it happens in the cytoplasm.","Saying fermentation yields ATP per glucose equal to aerobic respiration — it's only 2."],pyqs:[{q:"The site of the Krebs cycle is:",options:["mitochondrial matrix","cytoplasm","chloroplast","nucleus"],answer:0,explanation:"Krebs cycle runs in the matrix; ETC is on the inner membrane."},{q:"RQ of carbohydrates is approximately:",options:["1","0.7","0.9","1.5"],answer:0,explanation:"C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O ⇒ RQ = 6/6 = 1."}],tip:"Track the location: glycolysis = cytoplasm, Krebs = matrix, ETC = inner membrane."},"biology:biology-c13":{summary:"Plant Growth and Development covers growth phases, plant hormones, photoperiodism and vernalisation.",keyPoints:["Growth phases: meristematic, elongation, maturation; arithmetic vs geometric growth curves.","Auxin: cell elongation, apical dominance, phototropism; IAA, IBA, NAA.","Gibberellins: stem elongation, bolting, seed germination; Cytokinins: cell division, delay senescence.","ABA: stress hormone — stomatal closure, dormancy, abscission; Ethylene: ripening, senescence.","Photoperiodism: response to day length — SDP (rice), LDP (wheat); Vernalisation: cold treatment for flowering."],glossary:[{term:"Apical dominance",def:"Suppression of lateral buds by the apex (auxin effect).",hindi:"शीर्ष प्रभुत्व"},{term:"Photoperiodism",def:"Flowering response to relative day/night length.",hindi:"प्रकाशकालिता"}],mistakes:["Matching ABA to growth promotion — it is a stress/growth inhibitor.","Saying ethylene promotes leaf growth — it promotes ripening and abscission."],pyqs:[{q:"Stomatal closure during drought is caused by:",options:["ABA","auxin","GA","cytokinin"],answer:0,explanation:"ABA closes stomata to conserve water."},{q:"Bolt in cabbage (internode elongation) is induced by:",options:["gibberellins","auxins","cytokinins","ethylene"],answer:0,explanation:"GA causes rapid stem elongation (bolting)."}],tip:"One hormone ↔ one headline effect — ABA=dormancy/stress, GA=elongation, Ethylene=ripening."},"biology:biology-c14":{summary:"Breathing and Exchange of Gases covers respiratory organs, the breathing mechanism, gas transport and its regulation.",keyPoints:["Human respiration: nostrils → pharynx → larynx → trachea → bronchi → bronchioles → alveoli.","Breathing: inspiration (diaphragm & external intercostals contract) and expiration (passive, elastic recoil).","Intrapulmonary pressure −1 to −3 mm Hg relative to atmosphere drives air in; intrapleural pressure is always negative.","O₂ transport: 97% with haemoglobin (oxyhaemoglobin), 3% dissolved; CO₂: 70% as bicarbonate, 20–25% carbamino, 7% dissolved.","Regulation: respiratory rhythm centre (medulla), pneumotaxic centre (limits inspiration), chemoreceptors sense CO₂/H⁺."],glossary:[{term:"Tidal volume",def:"Air per normal breath (~500 mL).",hindi:"ज्वारीय आयतन"},{term:"Vital capacity",def:"TV + IRV + ERV — maximum air after deepest breath.",hindi:"महत्वपूर्ण क्षमता"}],mistakes:["Saying CO₂ binds to haemoglobin as carbamino — it does, but most travels as bicarbonate.","Calling expiration an active process — normal expiration is passive."],pyqs:[{q:"Maximum CO₂ is transported in blood as:",options:["bicarbonate","carbamino compounds","dissolved gas","oxyhaemoglobin"],answer:0,explanation:"About 70% travels as bicarbonate ions."},{q:"The respiratory rhythm centre is located in the:",options:["medulla oblongata","cerebellum","cerebrum","pons only"],answer:0,explanation:"The medulla's respiratory rhythm centre paces breathing."}],tip:"Lung volume sums: VC = TV + IRV + ERV — know the four standard volumes."},"biology:biology-c15":{summary:"Body Fluids and Circulation covers blood, blood groups, lymph, the heart, cardiac cycle and ECG.",keyPoints:["Plasma: 55%, water + proteins (albumin, globulins, fibrinogen); formed elements: RBC, WBC, platelets.","ABO system: A, B, AB, O with antibodies; Rh: Rh⁺/Rh⁻ — erythroblastosis fetalis risk in Rh⁻ mother + Rh⁺ baby.","Heart: SA node (pacemaker) → AV node → bundle of His → Purkinje fibres.","Cardiac cycle: atrial systole, ventricular systole, joint diastole; heart rate ~72/min.","ECG: P wave (atrial depolarisation), QRS (ventricular depolarisation), T wave (ventricular repolarisation)."],glossary:[{term:"Pacemaker",def:"SA node initiating the heartbeat.",hindi:"पेसमेकर"},{term:"Systole/Diastole",def:"Contraction / relaxation phases of the heart chambers.",hindi:"प्रकुंचन/प्रसारण"}],mistakes:["Giving blood group O both A and B antigens — O has neither, but both antibodies.","Saying the QRS complex is atrial depolarisation — it's ventricular."],pyqs:[{q:"The natural pacemaker of the heart is:",options:["SA node","AV node","Purkinje fibres","Bundle of His"],answer:0,explanation:"SA node sets the cardiac rhythm."},{q:"A person with blood group AB has:",options:["no antibodies","anti-A only","anti-B only","anti-A and anti-B"],answer:0,explanation:"AB blood has both antigens, so no antibodies."}],tip:"ABO tables are free marks — memorise antigens vs antibodies per group."},"biology:biology-c16":{summary:"Excretory Products and their Elimination covers the kidney, nephron, urine formation and osmoregulation.",keyPoints:["Human excretory system: kidneys, ureters, urinary bladder, urethra; nephron = functional unit.","Nephron: Bowman's capsule, PCT, loop of Henle (descending/ascending), DCT, collecting duct.","Urine formation: glomerular filtration (~180 L/day), reabsorption, tubular secretion.","Countercurrent mechanism: loop of Henle + vasa recta concentrate urine.","Regulation: ADH (water reabsorption), aldosterone (Na⁺ reabsorption, K⁺ excretion), ANF (opposes RAAS)."],glossary:[{term:"Glomerular filtration",def:"Blood plasma filtered into Bowman's capsule at high pressure.",hindi:"ग्लोमेरुलर निस्यंदन"},{term:"Countercurrent mechanism",def:"Opposing flow in loop of Henle and vasa recta that concentrates urine.",hindi:"प्रतिधारा तंत्र"}],mistakes:["Saying ADH decreases water reabsorption — it increases it.","Calling the descending limb impermeable to water — it is permeable to water, impermeable to salts."],pyqs:[{q:"ADH increases:",options:["water reabsorption","salt excretion","blood pressure always","urine volume"],answer:0,explanation:"ADH makes collecting ducts reabsorb more water, concentrating urine."},{q:"The countercurrent mechanism involves:",options:["loop of Henle and vasa recta","only PCT","only glomerulus","ureters"],answer:0,explanation:"Opposing flows of filtrate and blood build the medullary gradient."}],tip:"One-line nephron map: filtration in Bowman's, bulk reabsorption in PCT, concentration in the loop."},"biology:biology-c17":{summary:"Locomotion and Movement covers muscle types, the sliding filament theory, the skeleton and joints.",keyPoints:["Muscle types: skeletal (striated, voluntary), smooth (unstriated, involuntary), cardiac (striated, involuntary).","Sarcomere: Z-line to Z-line; actin (thin) and myosin (thick) filaments.","Sliding filament: myosin heads pull actin; requires ATP and Ca²⁺; rigor mortis = no ATP after death.","Skeleton: 206 bones; axial (skull, vertebral column, ribs) + appendicular (limbs, girdles).","Joints: fibrous, cartilaginous, synovial (ball & socket, hinge, pivot)."],glossary:[{term:"Sarcomere",def:"Functional unit of a myofibril between two Z-lines.",hindi:"सार्कोमियर"},{term:"Rigor mortis",def:"Muscle stiffening after death due to ATP absence.",hindi:"मृत्यु कठोरता"}],mistakes:["Calling cardiac muscle voluntary — it is involuntary.","Saying troponin is absent in smooth muscle regulation — smooth muscle uses calmodulin instead."],pyqs:[{q:"The functional unit of muscle contraction is:",options:["sarcomere","myofibril","muscle fibre","sarcolemma"],answer:0,explanation:"Sarcomeres between Z-lines shorten during contraction."},{q:"Which muscle is voluntary and striated?",options:["skeletal","smooth","cardiac","visceral"],answer:0,explanation:"Skeletal muscle is striated and under voluntary control."}],tip:"Contraction needs both ATP and Ca²⁺ — 'no ATP' explains rigor mortis questions."},"biology:biology-c18":{summary:"Neural Control and Coordination covers neurons, nerve impulses, synapses, the nervous system and sense organs.",keyPoints:["Neuron: dendrites, cell body, axon; myelin sheath speeds conduction (saltatory).","Resting potential: −70 mV (Na⁺-K⁺ pump, K⁺ leak); action potential: Na⁺ in (depolarise), K⁺ out (repolarise).","Synapse: chemical transmission via neurotransmitters (acetylcholine); summation and inhibition.","CNS: brain (cerebrum, cerebellum, medulla) + spinal cord; PNS: cranial and spinal nerves; ANS: sympathetic (fight/flight) + parasympathetic.","Reflex arc: receptor → sensory neuron → spinal cord → motor neuron → effector."],glossary:[{term:"Action potential",def:"Rapid depolarisation-repolarisation wave along the axon.",hindi:"क्रिया विभव"},{term:"Synapse",def:"Junction where a neuron signals another cell via neurotransmitters.",hindi:"सिनैप्स"}],mistakes:["Saying the resting membrane is positive inside — it's negative (−70 mV).","Calling the sympathetic system 'rest and digest' — that's parasympathetic."],pyqs:[{q:"The resting membrane potential of a neuron is about:",options:["−70 mV","+70 mV","0 mV","+35 mV"],answer:0,explanation:"K⁺ leak and Na⁺-K⁺ pump maintain ≈ −70 mV."},{q:"Which system prepares the body for emergencies?",options:["sympathetic","parasympathetic","somatic","enteric"],answer:0,explanation:"Sympathetic activation = fight-or-flight response."}],tip:"Depolarisation = Na⁺ in; repolarisation = K⁺ out — the two-ion story."},"biology:biology-c19":{summary:"Chemical Coordination and Integration covers endocrine glands, hormones and their disorders.",keyPoints:["Hypothalamus: releasing/inhibiting hormones controlling the pituitary.","Pituitary: growth hormone, TSH, ACTH, FSH, LH, prolactin, oxytocin, ADH (posterior).","Thyroid (T₃, T₄): metabolism; hypothyroidism → goitre/cretinism; hyper → Graves' disease.","Adrenal: cortex (cortisol, aldosterone) + medulla (adrenaline — fight or flight).","Pancreas: insulin (lowers glucose) and glucagon (raises it); diabetes mellitus from insulin deficiency."],glossary:[{term:"Hormone",def:"Chemical messenger transported by blood to target organs.",hindi:"हार्मोन"},{term:"Feedback regulation",def:"Hormone levels self-adjust (e.g. thyroid–TSH loop).",hindi:"पुनर्भरण विनियमन"}],mistakes:["Saying insulin increases blood glucose — glucagon does that.","Putting oxytocin and ADH in the anterior pituitary — they come from the posterior lobe."],pyqs:[{q:"Insulin is secreted by:",options:["beta cells of islets","alpha cells","thyroid","adrenal medulla"],answer:0,explanation:"β-cells make insulin; α-cells make glucagon."},{q:"Graves' disease is due to:",options:["thyroid overactivity","thyroid underactivity","insulin excess","cortisol deficiency"],answer:0,explanation:"Excess thyroid hormone causes Graves' disease."}],tip:"Build a hormone↔gland↔effect↔disorder table — it's the entire exam for this chapter."},"biology:biology-c20":{summary:"Sexual Reproduction in Flowering Plants covers gametophytes, pollination, double fertilisation and seed development.",keyPoints:["Microsporogenesis: pollen mother cells → microspores → pollen grains (male gametophyte).","Megasporogenesis: one functional megaspore → embryo sac (8-nucleate, 7-celled).","Pollination: self vs cross; agents — wind (anemophily), insects (entomophily), birds, water.","Double fertilisation: one sperm + egg → zygote; second sperm + polar nuclei → endosperm (3n).","Post-fertilisation: ovule → seed, ovary → fruit; apomixis (asexual seeds) and polyembryony."],glossary:[{term:"Double fertilisation",def:"Both sperm fuse — one with egg, one with polar nuclei.",hindi:"द्वि-निषेचन"},{term:"Endosperm",def:"Triploid nutritive tissue feeding the embryo.",hindi:"भ्रूणपोष"}],mistakes:["Saying the embryo sac is diploid — the mature embryo sac is haploid.","Calling endosperm diploid — it is triploid (3n) in angiosperms."],pyqs:[{q:"Endosperm of angiosperms is:",options:["triploid","diploid","haploid","tetraploid"],answer:0,explanation:"Fusion of one sperm with two polar nuclei gives 3n endosperm."},{q:"Pollination by insects is called:",options:["entomophily","anemophily","hydrophily","ornithophily"],answer:0,explanation:"Insect pollination = entomophily."}],tip:"Double fertilisation: 1 zygote (2n) + 1 endosperm (3n) — always recheck ploidy."},"biology:biology-c21":{summary:"Human Reproduction covers the reproductive systems, gametogenesis, the menstrual cycle, fertilisation and pregnancy.",keyPoints:["Male system: testes (spermatogenesis), epididymis, vas deferens, seminal vesicles, prostate.","Female system: ovaries, oviducts (fallopian tubes), uterus, cervix, vagina; mammary glands.","Spermatogenesis: in seminiferous tubules, 64 days; primary spermatocyte (2n) → 4 spermatids (n).","Oogenesis: begins in foetal life; arrests at prophase I; completed at fertilisation.","Menstrual cycle: menstrual → follicular → ovulation (day 14) → luteal; LH surge triggers ovulation; corpus luteum secretes progesterone."],glossary:[{term:"Gametogenesis",def:"Formation of gametes (spermatogenesis/oogenesis).",hindi:"युग्मकजनन"},{term:"Corpus luteum",def:"Progesterone-secreting structure from the ruptured follicle.",hindi:"पीत पिंड"}],mistakes:["Saying oogenesis is completed before birth — it arrests and finishes later.","Calling the LH surge a follicular-phase event — it triggers ovulation at mid-cycle."],pyqs:[{q:"Ovulation occurs around which day of a 28-day cycle?",options:["14","7","21","28"],answer:0,explanation:"LH surge around day 14 releases the secondary oocyte."},{q:"Spermatogenesis occurs in:",options:["seminiferous tubules","epididymis","prostate","vas deferens"],answer:0,explanation:"Seminiferous tubules of the testes make sperm."}],tip:"Draw the menstrual cycle as a line with four phases and one hormone per phase."},"biology:biology-c22":{summary:"Reproductive Health covers population control, contraception, MTP, STDs and assisted reproductive technologies.",keyPoints:["Population explosion: need for family planning; reproductive health = total well-being of reproductive systems.","Contraception: natural (rhythm, withdrawal), barrier (condoms, diaphragm), IUDs (Cu-T), hormonal pills, surgical (vasectomy, tubectomy).","MTP: safe, legal termination of pregnancy; done to avoid unwanted births and foetal risks.","STDs: syphilis, gonorrhoea, AIDS, genital herpes — preventable by barrier methods.","ART: IVF-ET, ZIFT, GIFT, ICSI, AI, surrogacy — for infertility treatment."],glossary:[{term:"IUD",def:"Intrauterine device (e.g. Cu-T) preventing implantation/pregnancy.",hindi:"अंतर्गर्भाशयी युक्ति"},{term:"IVF",def:"Fertilisation of egg and sperm outside the body, embryo transferred to uterus.",hindi:"टेस्ट-ट्यूब शिशु विधि"}],mistakes:["Saying MTP is done for sex selection — it's for safe termination, not sex determination.","Calling all STDs curable — viral ones (AIDS, herpes) are not fully curable."],pyqs:[{q:"Cu-T is an example of:",options:["IUD","barrier","hormonal pill","surgical method"],answer:0,explanation:"Copper-T is an intrauterine device."},{q:"A permanent contraceptive method is:",options:["vasectomy","condoms","Cu-T","oral pills"],answer:0,explanation:"Vasectomy (male) and tubectomy (female) are surgical and permanent."}],tip:"Match each contraceptive to its category — natural/barrier/IUD/hormonal/surgical."},"biology:biology-c23":{summary:"Principles of Inheritance and Variation covers Mendel's laws, crosses, gene interactions, linkage, sex determination and mutations.",keyPoints:["Mendel's laws: dominance, segregation, independent assortment (dihybrid 9:3:3:1).","Monohybrid: 3:1 phenotypic, 1:2:1 genotypic; test cross reveals genotype.","Incomplete dominance (4 o'clock: 1:2:1), codominance (ABO), multiple alleles.","Linkage: genes on the same chromosome inherit together; crossing over breaks linkage.","Sex determination: humans XY (male heterogametic); chromosomal disorders — Down (trisomy 21), Turner (XO), Klinefelter (XXY)."],formulas:[{name:"Dihybrid ratio",formula:"9 : 3 : 3 : 1 (independent assortment)"},{name:"Monohybrid ratio",formula:"3 : 1 (F₂ phenotype)"}],glossary:[{term:"Allele",def:"Alternative form of a gene at the same locus.",hindi:"युग्म विकल्पी"},{term:"Linkage",def:"Tendency of genes on one chromosome to inherit together.",hindi:"जीन संबंधन"}],mistakes:["Using 9:3:3:1 for monohybrid crosses — that's the dihybrid F₂.","Calling Turner syndrome XXY — Turner is XO; Klinefelter is XXY."],pyqs:[{q:"The F₂ phenotypic ratio of a monohybrid cross is:",options:["3:1","9:3:3:1","1:2:1","1:1"],answer:0,explanation:"Dominant:recessive = 3:1 in monohybrid F₂."},{q:"Klinefelter's syndrome has the genotype:",options:["XXY","XO","XXX","XYY"],answer:0,explanation:"XXY males with small testes and gynaecomastia."}],tip:"Memorise the five classic ratios: 3:1, 1:2:1, 9:3:3:1, 1:1, 1:1:1:1 — match the cross."},"biology:biology-c24":{summary:"Molecular Basis of Inheritance covers DNA structure, replication, transcription, translation, the genetic code and the lac operon.",keyPoints:["DNA: double helix, antiparallel, A=T & G≡C (Chargaff), Watson & Crick; packaging with histones → nucleosomes.","Replication: semi-conservative (Meselson-Stahl); DNA polymerase adds 5'→3'; leading/lagging strands.","Transcription: DNA → RNA by RNA polymerase; in eukaryotes hnRNA processed (splicing) to mRNA.","Genetic code: triplet, degenerate, universal, non-overlapping; AUG start, UAA/UAG/UGA stop.","Lac operon: inducer (lactose) removes repressor → structural genes express; regulation of gene expression."],glossary:[{term:"Nucleosome",def:"DNA wrapped around histone octamer — packaging unit.",hindi:"न्यूक्लियोसोम"},{term:"Genetic code",def:"Triplet codons mapping mRNA to amino acids.",hindi:"आनुवंशिक कूट"}],mistakes:["Saying DNA polymerase builds 3'→5' — synthesis is always 5'→3'.","Calling the code overlapping — it is non-overlapping and comma-less."],pyqs:[{q:"DNA replication is:",options:["semi-conservative","conservative","dispersive","random"],answer:0,explanation:"Meselson & Stahl proved semi-conservative replication."},{q:"The start codon is:",options:["AUG","UAA","UAG","UGA"],answer:0,explanation:"AUG codes for methionine and starts translation."}],tip:"The four code facts — triplet, degenerate, universal, non-overlapping — are guaranteed NEET lines."},"biology:biology-c25":{summary:"Evolution covers the origin of life, evidence, natural selection, speciation and the Hardy-Weinberg principle.",keyPoints:["Origin of life: Oparin-Haldane + Miller-Urey experiment synthesised amino acids from inorganic gases.","Evidence: fossils, homologous organs (common ancestor), analogous organs (convergent), embryological.","Natural selection: Darwin; peppered moth (industrial melanism), antibiotic resistance.","Speciation: reproductive isolation + genetic drift + natural selection; adaptive radiation (Darwin's finches).","Hardy-Weinberg: p² + 2pq + q² = 1; allele frequencies stable without mutation, selection, drift, migration."],formulas:[{name:"Hardy-Weinberg",formula:"p² + 2pq + q² = 1, p + q = 1"}],glossary:[{term:"Homologous organs",def:"Same origin, different functions (forelimbs of vertebrates).",hindi:"समजात अंग"},{term:"Adaptive radiation",def:"One ancestral form diversifying into many ecological niches.",hindi:"अनुकूली विकिरण"}],mistakes:["Calling homologous organs evidence of convergent evolution — they show divergent evolution.","Saying mutation rates alone drive Hardy-Weinberg equilibrium — mutation breaks equilibrium."],pyqs:[{q:"Hardy-Weinberg equilibrium is disturbed by:",options:["natural selection","random mating","large population","no migration"],answer:0,explanation:"Selection changes allele frequencies; the equilibrium assumes none."},{q:"Industrial melanism in moths is an example of:",options:["natural selection","genetic drift","mutation","migration"],answer:0,explanation:"Dark moths survived sooty trees — selection acting on variation."}],tip:"HH equation: if p = 0.7, then q = 0.3 and heterozygotes = 2pq = 0.42 — practice this once."},"biology:biology-c26":{summary:"Human Health and Disease covers pathogens, immunity, AIDS, cancer and drug abuse.",keyPoints:["Infectious diseases: typhoid (Salmonella), pneumonia (Streptococcus), malaria (Plasmodium via Anopheles), dengue (Aedes).","Immunity: innate (non-specific) + acquired (specific); humoral (antibodies) vs cell-mediated (T-cells).","Vaccines: passive (ready antibodies) vs active (antigen exposure); memory cells give long immunity.","AIDS: HIV attacks helper T-cells; transmitted by blood, sex, mother to child — not by touch/sharing utensils.","Cancer: uncontrolled cell division; oncogenes; treatments — surgery, radiation, chemo, immunotherapy."],glossary:[{term:"Antibody",def:"Protein (immunoglobulin) binding specific antigens.",hindi:"प्रतिरक्षी"},{term:"Vaccination",def:"Exposure to weakened antigen building active immunity.",hindi:"टीकाकरण"}],mistakes:["Saying HIV spreads by mosquito bites — it does not.","Calling innate immunity specific — it is non-specific (skin, phagocytes, inflammation)."],pyqs:[{q:"Malaria is caused by:",options:["Plasmodium","Salmonella","Streptococcus","Wuchereria"],answer:0,explanation:"Plasmodium, transmitted by Anopheles mosquito, causes malaria."},{q:"HIV primarily destroys:",options:["helper T-cells","red blood cells","platelets","neurons"],answer:0,explanation:"HIV targets CD4⁺ helper T-cells, collapsing immunity."}],tip:"Disease↔pathogen↔vector tables are the highest-yield revision in this chapter."},"biology:biology-c27":{summary:"Microbes in Human Welfare shows how microbes make household products, industrial goods, biogas and agriculture helpers.",keyPoints:["Household: curd (Lactobacillus), dough fermentation (yeast), cheese, idli/dosa batter.","Industrial: antibiotics (Penicillium), organic acids (Aspergillus → citric acid), enzymes (lipase, protease in detergents).","Ethanol by Saccharomyces cerevisiae; beverages from fermentation.","Sewage treatment: primary (physical) + secondary (biological, BOD drop); biogas (methanogens) from sludge.","Biocontrol (Trichoderma, Baculovirus) and biofertilisers (Rhizobium, Azotobacter, mycorrhiza, BGA)."],glossary:[{term:"BOD",def:"Oxygen needed to decompose organic matter — lower BOD = cleaner water.",hindi:"BOD"},{term:"Biofertiliser",def:"Living organisms enriching soil nutrients (Rhizobium, BGA).",hindi:"जैव उर्वरक"}],mistakes:["Saying biogas is produced in the primary clarifier — methanogens act in anaerobic sludge digesters.","Calling antibiotics produced by bacteria only — Penicillium is a fungus."],pyqs:[{q:"Curd is formed by:",options:["Lactobacillus","Saccharomyces","Rhizobium","Penicillium"],answer:0,explanation:"Lactobacillus ferments milk into curd."},{q:"Biogas mainly contains:",options:["methane","CO₂","hydrogen","oxygen"],answer:0,explanation:"Methanogens produce methane-rich biogas."}],tip:"One microbe ↔ one product: Lactobacillus-curd, Penicillium-penicillin, Saccharomyces-ethanol."},"biology:biology-c28":{summary:"Biotechnology: Principles and Processes covers the tools — restriction enzymes, cloning vectors, PCR, gel electrophoresis.",keyPoints:["Genetic engineering: cut (restriction enzymes), join (ligase), insert (vector), amplify (PCR/cloning).","Restriction enzymes: cut at palindromic sequences; EcoRI leaves sticky ends.","Cloning vectors: origin of replication, selectable markers (ampicillin resistance), MCS; pBR322, pUC19.","PCR: denaturation (94 °C) → annealing (primers) → extension (Taq polymerase) — amplifies DNA in vitro.","Gel electrophoresis: DNA moves to anode through agarose; ethidium bromide stains it; Southern blotting detects it."],glossary:[{term:"Restriction enzyme",def:"Molecular scissors cutting DNA at specific palindromic sites.",hindi:"प्रतिबंध एंजाइम"},{term:"Vector",def:"DNA carrier (plasmid) ferrying the gene of interest.",hindi:"वाहक"},{term:"PCR",def:"Polymerase chain reaction amplifying a DNA segment.",hindi:"PCR"}],mistakes:["Saying ligase cuts DNA — ligase joins; restriction enzymes cut.","Giving sticky ends to blunt-cut enzymes like SmaI — SmaI makes blunt ends."],pyqs:[{q:"Restriction enzymes cut DNA at:",options:["palindromic sequences","random sites","telomeres","centromeres"],answer:0,explanation:"Recognition sites are palindromic, e.g. GAATTC for EcoRI."},{q:"Taq polymerase is used in PCR because it:",options:["is thermostable","works at low temperature","is a ligase","unwinds DNA"],answer:0,explanation:"Taq survives the 94 °C denaturation step."}],tip:"Remember the toolbox order: cut with restriction enzyme, insert with ligase, multiply with PCR."},"biology:biology-c29":{summary:"Biotechnology and its Applications covers GM crops, Bt cotton, recombinant insulin, gene therapy and ethical issues.",keyPoints:["GM crops: inserted genes for pest resistance, increased nutrition; golden rice (pro-vitamin A).","Bt cotton: cry genes from Bacillus thuringiensis produce Bt toxin killing bollworms.","RNAi: silences parasite genes (nematode-resistant tobacco).","Recombinant insulin (Humulin): E. coli with human insulin genes — first biotech medicine.","Gene therapy: correct defective genes (adenosine deaminase deficiency); ethics — patents, GM safety, biopiracy."],glossary:[{term:"Bt toxin",def:"Insecticidal protein from Bacillus thuringiensis, harmless to humans.",hindi:"Bt विष"},{term:"RNA interference",def:"Silencing gene expression with complementary RNA.",hindi:"RNA हस्तक्षेप"},{term:"Gene therapy",def:"Correcting defective genes to treat disease.",hindi:"जीन चिकित्सा"}],mistakes:["Saying Bt toxin is produced by the plant's own genes — it's the bacterial cry gene inserted.","Calling golden rice protein-rich — it is provitamin-A enriched."],pyqs:[{q:"Bt cotton is resistant to:",options:["insect pests","fungi","viruses","herbicides only"],answer:0,explanation:"Bt toxin kills bollworms and other chewing pests."},{q:"The first clinical gene therapy treated:",options:["adenosine deaminase deficiency","diabetes","cancer","thalassemia"],answer:0,explanation:"ADA deficiency was the first gene-therapy target (1990)."}],tip:"For application MCQs, link the product to its purpose: Bt→pest, insulin→diabetes, RNAi→nematode."},"biology:biology-c30":{summary:"Organisms and Populations covers habitat, niche, population attributes, growth models and species interactions.",keyPoints:["Habitat: where a species lives; niche: its role/function (including resource use).","Population attributes: density, natality, mortality, age structure, sex ratio, dispersal.","Growth models: exponential (J-shaped, r) and logistic (S-shaped, with K carrying capacity).","Interactions: predation, competition (Gause's exclusion), parasitism, commensalism, mutualism, amensalism.","Adaptations: physiological (desert), behavioural (migration), morphological (camouflage)."],formulas:[{name:"Exponential growth",formula:"dN/dt = rN"},{name:"Logistic growth",formula:"dN/dt = rN(K − N)/K"}],glossary:[{term:"Niche",def:"Functional role of a species in its ecosystem.",hindi:"पारिस्थितिक निकेत"},{term:"Carrying capacity",def:"Maximum population an environment can sustain (K).",hindi:"धारण क्षमता"}],mistakes:["Confusing habitat with niche — habitat is the address, niche is the profession.","Saying predation always harms the prey population — predators often remove the weak, aiding regulation."],pyqs:[{q:"Logistic growth levels off at:",options:["carrying capacity K","zero","r","infinity"],answer:0,explanation:"The (K−N)/K term slows growth as N approaches K."},{q:"Barnacles on a whale's skin is an example of:",options:["commensalism","parasitism","mutualism","competition"],answer:0,explanation:"Barnacles benefit, the whale is unaffected — commensalism."}],tip:"Interaction pairs: +/0 commensalism, +/− parasitism, +/+ mutualism, −/− competition."},"biology:biology-c31":{summary:"Ecosystem covers components, productivity, decomposition, energy flow, nutrient cycling and succession.",keyPoints:["Components: abiotic + biotic (producers, consumers, decomposers); detritus food chain vs grazing food chain.","Productivity: GPP (total fixed) − R = NPP; productivity limited by light, water, nutrients.","Decomposition: detritivores + decomposers; humus; slowed by anaerobic/cold conditions.","Energy flow: 10% law (Lindeman) — only ~10% transfers between trophic levels.","Nutrient cycling: carbon, nitrogen, phosphorus cycles; succession: hydrarch → xerarch to climax."],formulas:[{name:"Net primary productivity",formula:"NPP = GPP − R"},{name:"10% law",formula:"Energy to next level ≈ 10% of previous"}],glossary:[{term:"Trophic level",def:"Feeding position in a food chain (producer, primary consumer…).",hindi:"पोषी स्तर"},{term:"Biomagnification",def:"Concentration of toxins rising up the food chain.",hindi:"जैव आवर्धन"}],mistakes:["Saying energy is recycled — matter cycles; energy flows one-way.","Putting decomposers in a trophic level of the food chain — they are outside it, cycling nutrients."],pyqs:[{q:"Only about what percentage of energy transfers between trophic levels?",options:["10%","50%","90%","1%"],answer:0,explanation:"Lindeman's 10% law governs ecological pyramids."},{q:"GPP minus respiration equals:",options:["NPP","biomass","detritus","secondary production"],answer:0,explanation:"NPP = GPP − R is what plants actually store."}],tip:"Pyramid of energy is always upright; numbers and biomass pyramids can be inverted."},"biology:biology-c32":{summary:"Biodiversity and Conservation covers biodiversity patterns, losses, hotspots and conservation strategies.",keyPoints:["Biodiversity: genetic, species, ecological diversity; tropical regions hold maximum.","Patterns: species richness increases towards the tropics; latitudinal gradient.","Losses: habitat loss (biggest cause), over-exploitation, invasive species, pollution, climate change.","Hotspots: 34 globally; India — Eastern Himalayas, Indo-Burma, Western Ghats & Sri Lanka.","Conservation: in-situ (national parks, sanctuaries, biosphere reserves) and ex-situ (zoos, botanical gardens, seed banks)."],glossary:[{term:"Biodiversity hotspot",def:"High endemic species + high threat region.",hindi:"जैव विविधता हॉटस्पॉट"},{term:"Endemism",def:"Species found only in one region.",hindi:"स्थानिकता"}],mistakes:["Saying in-situ means zoos — in-situ conserves in natural habitats; zoos are ex-situ.","Calling Western Ghats the only Indian hotspot — India has four regions in three hotspots."],pyqs:[{q:"The greatest threat to biodiversity is:",options:["habitat loss","pollution","climate change","hunting"],answer:0,explanation:"Habitat destruction fragments populations fastest."},{q:"Biosphere reserves are an example of:",options:["in-situ conservation","ex-situ conservation","both equally","captive breeding"],answer:0,explanation:"Protected natural areas conserve species in their habitats."}],tip:"Match conservation type to location: parks/sanctuaries = in-situ; zoos/banks = ex-situ."},"biology:biology-c33":{summary:"Environmental Issues covers pollution, waste, climate change and deforestation with their control measures.",keyPoints:["Air pollution: particulate matter, SO₂ (acid rain), smog; control via electrostatic precipitators, scrubbers.","Water pollution: BOD and COD measure organic load; algal blooms; biomagnification of DDT.","Solid waste: landfills, incineration, recycling; e-waste contains heavy metals needing special handling.","Global warming: greenhouse gases (CO₂, CH₄, N₂O, CFCs); sea-level rise, climate change.","Deforestation: soil erosion, biodiversity loss; measures — afforestation, Chipko movement, joint forest management."],glossary:[{term:"BOD",def:"Biochemical oxygen demand — higher BOD means more pollution.",hindi:"BOD"},{term:"Biomagnification",def:"Toxin concentration rising through the food chain.",hindi:"जैव आवर्धन"},{term:"Acid rain",def:"Rain acidified by SO₂ and NOₓ.",hindi:"अम्ल वर्षा"}],mistakes:["Saying high BOD means clean water — high BOD signals heavy organic pollution.","Calling CO₂ the only greenhouse gas — methane and CFCs are stronger per molecule."],pyqs:[{q:"Acid rain is mainly caused by:",options:["SO₂ and NOₓ","CO₂ only","CH₄","O₃"],answer:0,explanation:"Oxides of sulphur and nitrogen acidify rain."},{q:"Electrostatic precipitators control:",options:["particulate air pollution","water pollution","noise","radiation"],answer:0,explanation:"They charge and collect particulate matter from flue gases."}],tip:"Pair each pollutant with its effect: SO₂→acid rain, CFC→ozone hole, DDT→biomagnification."}},p={"maths:maths-c1":{summary:"Sets introduces the language of collections — representation, operations, Venn diagrams and laws of sets.",keyPoints:["A set is a well-defined collection; represented in roster (list) or set-builder form.","n(A ∪ B) = n(A) + n(B) − n(A ∩ B); for three sets add the triple intersection back.","De Morgan's laws: (A ∪ B)' = A' ∩ B'; (A ∩ B)' = A' ∪ B'.","Power set P(A) has 2ⁿ subsets for a set of n elements.","Disjoint sets have n(A ∩ B) = 0; subset relation A ⊆ B means every element of A is in B."],formulas:[{name:"Union cardinality",formula:"n(A∪B) = n(A) + n(B) − n(A∩B)"},{name:"Power set size",formula:"|P(A)| = 2ⁿ"}],glossary:[{term:"Subset",def:"A ⊆ B: all elements of A belong to B.",hindi:"उपसमुच्चय"},{term:"Universal set",def:"Set containing all elements under discussion, U.",hindi:"सार्वत्रिक समुच्चय"}],mistakes:["Forgetting that the empty set is a subset of every set.","Adding intersection twice in three-set union problems."],pyqs:[{q:"If n(A) = 5, the number of subsets of A is:",options:["32","25","10","5"],answer:0,explanation:"2⁵ = 32 subsets."},{q:"(A ∪ B)' equals:",options:["A' ∩ B'","A' ∪ B'","A ∩ B","A ∪ B"],answer:0,explanation:"De Morgan's law: complement of a union is the intersection of complements."}],tip:"Venn diagrams: start shading from the innermost bracket in set-identity questions."},"maths:maths-c2":{summary:"Relations and Functions (Class 11) defines relations, types of functions, domain, range and graphs.",keyPoints:["Relation R ⊆ A × B; domain = first set elements, range = second set elements that appear.","A function assigns exactly ONE output per input; vertical line test on graphs.","Types: one-one (injective), onto (surjective), bijective (both); check via horizontal line test.","Domain rules: denominators ≠ 0; radicands of even roots ≥ 0; log arguments > 0.","Common graphs: x² (parabola), 1/x (hyperbola), |x| (V-shape), √x (half parabola)."],glossary:[{term:"Domain",def:"Set of all valid inputs of a function.",hindi:"प्रांत"},{term:"Range",def:"Set of all outputs a function produces.",hindi:"परिसर"},{term:"Bijective",def:"Both one-one and onto — has an inverse.",hindi:"एकैक आच्छादक"}],mistakes:["Saying a relation is a function when one input maps to two outputs.","Forgetting x = 0 exclusion for f(x) = 1/x when finding domains."],pyqs:[{q:"The domain of f(x) = √(x − 2) is:",options:["[2, ∞)","(2, ∞)","(−∞, 2]","R"],answer:0,explanation:"x − 2 ≥ 0 ⇒ x ≥ 2."},{q:"A function that is both one-one and onto is called:",options:["bijective","injective only","surjective only","constant"],answer:0,explanation:"Bijective = injective + surjective."}],tip:"Domain problems: list the three killers — division by zero, even roots, logarithms."},"maths:maths-c3":{summary:"Trigonometric Functions covers angles, identities, compound angles, transformation formulae and equations.",keyPoints:["Radian measure: π radians = 180°; arc length s = rθ.","Fundamental identities: sin²θ + cos²θ = 1; 1 + tan²θ = sec²θ; 1 + cot²θ = cosec²θ.","Compound: sin(A±B), cos(A±B), tan(A±B); double angles; half angles.","Transformation: 2sinA cosB = sin(A+B) + sin(A−B) etc.","General solutions: sinθ = 0 ⇒ θ = nπ; cosθ = 0 ⇒ θ = (2n+1)π/2; tanθ = 0 ⇒ θ = nπ."],formulas:[{name:"sin(A+B)",formula:"sinA cosB + cosA sinB"},{name:"cos(A+B)",formula:"cosA cosB − sinA sinB"},{name:"sin2θ",formula:"2 sinθ cosθ"},{name:"Product to sum",formula:"2 sinA cosB = sin(A+B) + sin(A−B)"}],glossary:[{term:"Radian",def:"Angle subtended by an arc equal to the radius.",hindi:"रेडियन"},{term:"General solution",def:"Formula describing all solutions of a trig equation.",hindi:"व्यापक हल"}],mistakes:["Mixing up the sign in cos(A+B) — cosA cosB MINUS sinA sinB.","Forgetting to add the period when writing general solutions."],pyqs:[{q:"sin75° equals:",options:["(√3+1)/(2√2)","(√3−1)/(2√2)","√3/2","1/2"],answer:0,explanation:"sin(45°+30°) = sin45 cos30 + cos45 sin30 = (√3+1)/(2√2)."},{q:"The general solution of sinθ = 0 is:",options:["θ = nπ","θ = (2n+1)π/2","θ = nπ/2","θ = 2nπ"],answer:0,explanation:"Sine vanishes at all multiples of π."}],tip:"Memorise the standard angle table (0°, 30°, 45°, 60°, 90°) — most trig MCQs reduce to it."},"maths:maths-c4":{summary:"Complex Numbers and Quadratic Equations covers complex algebra, modulus-argument form, De Moivre's theorem and quadratic roots.",keyPoints:["i² = −1; z = a + bi; conjugate z̄ = a − bi; z·z̄ = |z|².","Modulus |z| = √(a² + b²); argument arg(z) = tan⁻¹(b/a) with the correct quadrant.","Polar form: z = r(cosθ + i sinθ); De Moivre: (cosθ + i sinθ)ⁿ = cos nθ + i sin nθ.","Quadratic ax² + bx + c = 0: roots = [−b ± √(b² − 4ac)]/2a; complex roots occur in conjugate pairs.","Nature of roots via discriminant D = b² − 4ac: D > 0 real distinct, D = 0 equal, D < 0 complex."],formulas:[{name:"Modulus",formula:"|z| = √(a² + b²)"},{name:"Quadratic roots",formula:"x = (−b ± √(b² − 4ac)) / 2a"},{name:"De Moivre",formula:"(cosθ + i sinθ)ⁿ = cos(nθ) + i sin(nθ)"}],glossary:[{term:"Conjugate",def:"a − bi for z = a + bi; product gives |z|².",hindi:"संयुग्मी"},{term:"Argument",def:"Angle the complex vector makes with the positive real axis.",hindi:"कोणांक"}],mistakes:["Placing the argument in the wrong quadrant — check the signs of a and b.","Writing −1 as i² incorrectly in simplifications — i² = −1, i³ = −i, i⁴ = 1."],pyqs:[{q:"If z = 3 + 4i, then |z| is:",options:["5","7","25","1"],answer:0,explanation:"|z| = √(9 + 16) = 5."},{q:"The roots of x² + 1 = 0 are:",options:["±i","±1","0 and 1","±√2"],answer:0,explanation:"x² = −1 ⇒ x = ±i."}],tip:"For quadratics with complex roots, the sum is −b/a and product c/a — Vieta works for complex too."},"maths:maths-c5":{summary:"Linear Inequalities solves single and two-variable inequalities, including graphical regions.",keyPoints:["Multiplying/dividing by a NEGATIVE number flips the inequality sign.","Solution sets are intervals; strict vs non-strict matters at endpoints.","Two-variable inequality ax + by ≤ c defines a half-plane; test a point (0,0) to choose the region.","Systems of inequalities: feasible region = intersection of half-planes.","Integer solutions: list values satisfying the inequality within the domain."],glossary:[{term:"Half-plane",def:"Region of the plane satisfying a linear inequality.",hindi:"अर्ध-तल"},{term:"Feasible region",def:"Common region satisfying all constraints.",hindi:"सुसंगत क्षेत्र"}],mistakes:["Forgetting to flip the sign when dividing by a negative.","Shading the wrong half-plane — always test a sample point."],pyqs:[{q:"Solving −2x < 6 gives:",options:["x > −3","x < −3","x > 3","x < 3"],answer:0,explanation:"Divide by −2 and flip: x > −3."},{q:"The region x + y ≤ 4 lies:",options:["below the line x + y = 4","above the line","on the line only","right of the y-axis"],answer:0,explanation:"Test (0,0): 0 ≤ 4 true, and the origin lies below the line."}],tip:"The sign-flip on negatives is the single most common error — underline the divisor."},"maths:maths-c6":{summary:"Permutations and Combinations counts arrangements and selections — factorials, nPr, nCr and applications.",keyPoints:["Fundamental principle: if task 1 has m ways and task 2 has n ways, together m × n ways.","Permutations: nPr = n!/(n−r)! — order matters.","Combinations: nCr = n!/(r!(n−r)!) — order does not matter.","Circular arrangements of n distinct objects: (n−1)!; with clockwise/anticlockwise same: (n−1)!/2.","Identical objects: arrangements = n!/(p!q!…) when p, q objects repeat."],formulas:[{name:"Permutation",formula:"nPr = n! / (n−r)!"},{name:"Combination",formula:"nCr = n! / (r!(n−r)!)"},{name:"Circular arrangement",formula:"(n−1)!"}],glossary:[{term:"Permutation",def:"Ordered arrangement of objects.",hindi:"क्रमचय"},{term:"Combination",def:"Selection of objects ignoring order.",hindi:"संचय"}],mistakes:["Using permutations when order doesn't matter (committee problems → combinations).","Double counting identical arrangements in circular problems."],pyqs:[{q:"The number of ways to arrange 5 books on a shelf is:",options:["120","25","60","10"],answer:0,explanation:"5! = 120."},{q:"The number of ways to choose 2 students from 10 is:",options:["45","90","20","100"],answer:0,explanation:"10C2 = 10!/(2!8!) = 45."}],tip:"Ask one question first: does order matter? Permutation if yes, combination if no."},"maths:maths-c7":{summary:"Binomial Theorem expands (a + b)ⁿ with binomial coefficients and finds specific terms.",keyPoints:["(a + b)ⁿ = Σ nCr a^(n−r) b^r; there are n+1 terms.","General term: T(r+1) = nCr a^(n−r) b^r.","Middle term: one if n even (r = n/2), two if n odd.","Coefficient relations: nCr = nC(n−r); sum of all coefficients = 2ⁿ; alternating sum = 0.","Applications: approximations, divisibility problems, greatest term."],formulas:[{name:"General term",formula:"T(r+1) = nCr a^(n−r) b^r"},{name:"Coefficient sum",formula:"Σ nCr = 2ⁿ"},{name:"Symmetry",formula:"nCr = nC(n−r)"}],glossary:[{term:"Binomial coefficient",def:"nCr — the number attached to each term.",hindi:"द्विपद गुणांक"},{term:"General term",def:"Formula for the (r+1)-th term of the expansion.",hindi:"व्यापक पद"}],mistakes:["Forgetting the (−1)^r sign when expanding (a − b)ⁿ.","Starting the index at r = 1 for the general term — T(r+1) uses r = 0, 1, …"],pyqs:[{q:"The coefficient of x in (1 + x)¹⁰ is:",options:["10","1","45","120"],answer:0,explanation:"T₂ = 10C1 x ⇒ coefficient 10."},{q:"The sum of all binomial coefficients in (1 + x)ⁿ is:",options:["2ⁿ","n","n²","3ⁿ"],answer:0,explanation:"Put x = 1: (1 + 1)ⁿ = 2ⁿ."}],tip:"Independent-of-x terms: set the power of x in the general term to zero and solve for r."},"maths:maths-c8":{summary:"Sequences and Series covers AP, GP, harmonic progressions, AM-GM-HM and special sums.",keyPoints:["AP: a, a+d, …; nth term aₙ = a + (n−1)d; sum Sₙ = n/2 [2a + (n−1)d].","GP: a, ar, …; aₙ = ar^(n−1); sum = a(1−rⁿ)/(1−r); infinite sum = a/(1−r) for |r| < 1.","AM of two numbers = (a+b)/2; GM = √(ab); HM = 2ab/(a+b); AM ≥ GM ≥ HM.","Special sums: Σk = n(n+1)/2; Σk² = n(n+1)(2n+1)/6; Σk³ = [n(n+1)/2]².","Geometric mean between a and b: insert terms to form a GP."],formulas:[{name:"AP nth term",formula:"aₙ = a + (n−1)d"},{name:"GP infinite sum",formula:"S∞ = a/(1−r), |r| < 1"},{name:"Sum of squares",formula:"Σk² = n(n+1)(2n+1)/6"}],glossary:[{term:"Arithmetic progression",def:"Sequence with constant difference between terms.",hindi:"समांतर श्रेढ़ी"},{term:"Geometric progression",def:"Sequence with constant ratio between terms.",hindi:"गुणोत्तर श्रेढ़ी"}],mistakes:["Applying the infinite GP sum when |r| ≥ 1 — it diverges.","Using n/2[2a+(n−1)d] but counting the number of terms wrongly."],pyqs:[{q:"The sum 1 + 2 + 3 + … + 100 equals:",options:["5050","5000","10100","505"],answer:0,explanation:"n(n+1)/2 = 100 × 101/2 = 5050."},{q:"For two positive numbers, the correct order is:",options:["AM ≥ GM ≥ HM","AM ≤ GM ≤ HM","GM ≥ AM ≥ HM","HM ≥ AM ≥ GM"],answer:0,explanation:"AM ≥ GM ≥ HM with equality when numbers are equal."}],tip:"Inserting 'n' means between two numbers: common difference d = (b−a)/(n+1)."},"maths:maths-c9":{summary:"Straight Lines covers slope, equations of lines, angle between lines and distance formulas.",keyPoints:["Slope m = tanθ = (y₂−y₁)/(x₂−x₁); parallel lines have equal slopes, perpendicular m₁m₂ = −1.","Forms: point-slope, slope-intercept y = mx + c, two-point, intercept x/a + y/b = 1, general Ax + By + C = 0.","Angle between lines: tanθ = |(m₁−m₂)/(1+m₁m₂)|.","Distance of a point from a line: d = |Ax₁ + By₁ + C|/√(A² + B²).","Section formula: point dividing AB in m:n = (mx₂ + nx₁)/(m+n), (my₂ + ny₁)/(m+n)."],formulas:[{name:"Slope",formula:"m = (y₂ − y₁)/(x₂ − x₁)"},{name:"Point-line distance",formula:"d = |Ax₁ + By₁ + C| / √(A² + B²)"},{name:"Angle between lines",formula:"tanθ = |(m₁ − m₂)/(1 + m₁m₂)|"}],glossary:[{term:"Slope",def:"Tangent of the inclination angle of a line.",hindi:"ढाल"},{term:"Intercept form",def:"x/a + y/b = 1 where a, b are axis intercepts.",hindi:"अंत:खंड रूप"}],mistakes:["Writing m₁m₂ = 1 for perpendicular lines — it's −1.","Forgetting the absolute value in the distance formula."],pyqs:[{q:"The slope of the line 3x + 2y = 6 is:",options:["−3/2","3/2","2/3","−2/3"],answer:0,explanation:"y = −(3/2)x + 3 ⇒ m = −3/2."},{q:"Two lines are perpendicular if:",options:["m₁m₂ = −1","m₁ = m₂","m₁ + m₂ = 0","m₁m₂ = 1"],answer:0,explanation:"Product of slopes of perpendicular lines is −1."}],tip:"Distance-from-point questions: convert the line to general form FIRST."},"maths:maths-c10":{summary:"Conic Sections covers circles, parabolas, ellipses and hyperbolas with their standard equations.",keyPoints:["Circle: (x−h)² + (y−k)² = r²; centre (h,k), radius r.","Parabola y² = 4ax: focus (a,0), directrix x = −a, latus rectum 4a.","Ellipse x²/a² + y²/b² = 1: foci (±ae,0), e = √(1 − b²/a²), latus rectum 2b²/a.","Hyperbola x²/a² − y²/b² = 1: e = √(1 + b²/a²), asymptotes y = ±(b/a)x.","Conic from eccentricity: e = 0 circle, e = 1 parabola, e < 1 ellipse, e > 1 hyperbola."],formulas:[{name:"Parabola LR",formula:"Latus rectum = 4a"},{name:"Ellipse eccentricity",formula:"e = √(1 − b²/a²)"},{name:"Hyperbola eccentricity",formula:"e = √(1 + b²/a²)"}],glossary:[{term:"Focus",def:"Fixed point defining a conic with the directrix.",hindi:"नाभि"},{term:"Directrix",def:"Fixed line paired with the focus to define a conic.",hindi:"नियता"},{term:"Latus rectum",def:"Chord through the focus perpendicular to the axis.",hindi:"नाभिलंब"}],mistakes:["Using the parabola formula y² = 4ax when the axis is vertical (use x² = 4ay).","Swapping the ellipse/hyperbola eccentricity signs (1−b²/a² vs 1+b²/a²)."],pyqs:[{q:"The latus rectum of y² = 12x is:",options:["12","6","3","24"],answer:0,explanation:"4a = 12 from 4a = 12 ⇒ a = 3, LR = 12."},{q:"For a conic with e = 1, the conic is a:",options:["parabola","circle","ellipse","hyperbola"],answer:0,explanation:"Eccentricity exactly 1 defines the parabola."}],tip:"Identify the conic from the equation's squared terms: same sign = circle/ellipse, opposite = hyperbola."},"maths:maths-c11":{summary:"Introduction to Three Dimensional Geometry extends coordinates, distance and section formulas into space.",keyPoints:["Point in space: (x, y, z); coordinate planes xy, yz, zx.","Distance between P(x₁,y₁,z₁) and Q(x₂,y₂,z₂): √[(x₂−x₁)² + (y₂−y₁)² + (z₂−z₁)²].","Section formula in 3D mirrors the 2D formula applied to each coordinate.","Distance from origin: √(x² + y² + z²)."],formulas:[{name:"3D distance",formula:"d = √[(x₂−x₁)² + (y₂−y₁)² + (z₂−z₁)²]"}],glossary:[{term:"Coordinate plane",def:"Plane formed by two axes (xy, yz, zx).",hindi:"निर्देशांक तल"}],mistakes:["Dropping one squared term in the 3D distance formula.","Forgetting the section formula applies per-coordinate."],pyqs:[{q:"The distance between (1, 2, 2) and (2, 3, 4) is:",options:["√6","√5","3","2"],answer:0,explanation:"√[(1)² + (1)² + (2)²] = √6."}],tip:"3D formulas are 2D formulas with one more coordinate — spot the pattern, don't memorise fresh."},"maths:maths-c12":{summary:"Limits and Derivatives introduces the limit concept, standard limits and differentiation from first principles.",keyPoints:["Limit: value a function approaches as x → a; exists when left and right limits are equal.","Standard limits: lim sinx/x = 1 (x→0); lim (1 + 1/n)ⁿ = e; lim (aˣ−1)/x = ln a.","Derivative from first principles: f'(x) = lim [f(x+h) − f(x)]/h.","Algebra of derivatives: (u±v)' = u'±v'; (uv)' = u'v + uv'; (u/v)' = (u'v − uv')/v².","Derivatives of standard functions: xⁿ, sinx, cosx, eˣ, ln x, aˣ."],formulas:[{name:"Standard limit",formula:"lim_{x→0} sinx/x = 1"},{name:"First principle",formula:"f'(x) = lim_{h→0} [f(x+h) − f(x)]/h"},{name:"Product rule",formula:"(uv)' = u'v + uv'"}],glossary:[{term:"Limit",def:"Value a function tends to as the input approaches a point.",hindi:"सीमा"},{term:"Derivative",def:"Instantaneous rate of change; slope of the tangent.",hindi:"अवकलज"}],mistakes:["Using lim sinx/x = 1 when x → ∞ — it applies at x → 0.","Applying the quotient rule sign wrongly — numerator is u'v MINUS uv'."],pyqs:[{q:"lim_{x→0} sin(3x)/x equals:",options:["3","1","0","∞"],answer:0,explanation:"= 3 × lim sin(3x)/(3x) = 3 × 1 = 3."},{q:"The derivative of x³ is:",options:["3x²","x²","3x","x⁴/4"],answer:0,explanation:"d/dx xⁿ = nxⁿ⁻¹ ⇒ 3x²."}],tip:"For 0/0 limits, factorise and cancel BEFORE substituting — or use L'Hôpital if allowed."},"maths:maths-c13":{summary:"Statistics covers dispersion measures — range, mean deviation, variance and standard deviation.",keyPoints:["Range = max − min; simplest but ignores distribution shape.","Mean deviation about the mean/median uses absolute deviations.","Variance σ² = Σ(xᵢ − x̄)²/n; standard deviation σ = √variance.","For frequency data, weigh by frequencies: σ² = Σf(xᵢ−x̄)²/Σf.","Coefficient of variation = (σ/x̄) × 100 — compares variability across datasets."],formulas:[{name:"Variance",formula:"σ² = Σ(xᵢ − x̄)² / n"},{name:"CV",formula:"CV = (σ/x̄) × 100"}],glossary:[{term:"Mean deviation",def:"Average of absolute deviations from a central value.",hindi:"माध्य विचलन"},{term:"Standard deviation",def:"Root mean square deviation from the mean.",hindi:"मानक विचलन"}],mistakes:["Forgetting to square deviations before averaging in variance.","Using n vs n−1 (sample) inconsistently — NCERT uses n for the population formula."],pyqs:[{q:"If all observations are identical, the standard deviation is:",options:["0","1","x̄","undefined"],answer:0,explanation:"No spread means σ = 0."},{q:"Adding a constant c to every observation:",options:["doesn't change σ","adds c to σ","multiplies σ by c","squares σ"],answer:0,explanation:"Spread is shift-invariant; only scaling changes σ."}],tip:"Remember: σ is unaffected by adding constants, but scales by multiplication."},"maths:maths-c14":{summary:"Probability (Class 11) introduces sample spaces, events and the axiomatic definition of probability.",keyPoints:["P(A) = favourable outcomes / total outcomes (equally likely).","Sample space: set of all outcomes; events are subsets.","Addition rule: P(A∪B) = P(A) + P(B) − P(A∩B); mutually exclusive ⇒ P(A∩B) = 0.","Complement: P(A') = 1 − P(A).","Independent events: P(A∩B) = P(A)·P(B)."],formulas:[{name:"Addition rule",formula:"P(A∪B) = P(A) + P(B) − P(A∩B)"},{name:"Independence",formula:"P(A∩B) = P(A)·P(B)"}],glossary:[{term:"Sample space",def:"Set of all possible outcomes.",hindi:"प्रतिदर्श समष्टि"},{term:"Mutually exclusive",def:"Events that cannot occur together.",hindi:"परस्पर अपवर्जी"}],mistakes:["Treating dependent events as independent in the multiplication rule.","Forgetting to subtract the intersection in the addition rule."],pyqs:[{q:"The probability of getting an even number on a single die roll is:",options:["1/2","1/3","1/6","2/3"],answer:0,explanation:"3 favourable (2,4,6) out of 6 ⇒ 1/2."},{q:"If P(A) = 0.4 and P(B) = 0.5 with A, B independent, P(A∩B) is:",options:["0.2","0.9","0.45","0.1"],answer:0,explanation:"0.4 × 0.5 = 0.2."}],tip:"List the sample space explicitly for small problems — it prevents double counting."},"maths:maths-c15":{summary:"Relations and Functions (Class 12) deepens relations, functions, invertibility and binary operations.",keyPoints:["Relation types: reflexive, symmetric, transitive — equivalence relations have all three.","Function types: one-one/onto; composition (f∘g)(x) = f(g(x)).","Invertible ⇔ bijective; f⁻¹(f(x)) = x.","Binary operation on a set: closed mapping; identity and inverse elements."],glossary:[{term:"Equivalence relation",def:"Reflexive + symmetric + transitive.",hindi:"तुल्यता संबंध"},{term:"Composition",def:"Applying one function after another.",hindi:"संयोजन"}],mistakes:["Calling a relation an equivalence relation when one property is missing.","Composing in the wrong order — f∘g applies g first."],pyqs:[{q:"A relation that is reflexive, symmetric and transitive is called:",options:["equivalence","partial order","function","mapping"],answer:0,explanation:"All three properties define an equivalence relation."},{q:"A function is invertible if it is:",options:["bijective","injective only","surjective only","constant"],answer:0,explanation:"Only bijective functions have inverses."}],tip:"Check the three properties in order — one failure kills 'equivalence'."},"maths:maths-c16":{summary:"Inverse Trigonometric Functions defines principal branches, properties and identities.",keyPoints:["Inverse functions exist on restricted principal ranges: sin⁻¹ ∈ [−π/2, π/2], cos⁻¹ ∈ [0, π], tan⁻¹ ∈ (−π/2, π/2).","sin⁻¹(sin x) = x only inside the principal range.","Key identities: sin⁻¹x + cos⁻¹x = π/2; tan⁻¹x + cot⁻¹x = π/2; sec⁻¹x + cosec⁻¹x = π/2.","tan⁻¹x ± tan⁻¹y = tan⁻¹[(x ± y)/(1 ∓ xy)] with range checks.","Useful: sin⁻¹x = tan⁻¹[x/√(1−x²)]; converting between inverse forms."],formulas:[{name:"Complement identity",formula:"sin⁻¹x + cos⁻¹x = π/2"},{name:"Tangent sum",formula:"tan⁻¹x + tan⁻¹y = tan⁻¹[(x+y)/(1−xy)]"}],glossary:[{term:"Principal value",def:"Value of the inverse function within its principal branch.",hindi:"मुख्य मान"}],mistakes:["Saying sin⁻¹(sin 2π/3) = 2π/3 — the principal value is π/3.","Using the tan⁻¹ sum formula without checking xy < 1 / > 1 cases."],pyqs:[{q:"sin⁻¹x + cos⁻¹x equals:",options:["π/2","π","0","π/4"],answer:0,explanation:"The complementary identity holds for all x in [−1,1]."},{q:"The principal value of sin⁻¹(1/2) is:",options:["π/6","5π/6","π/3","2π/3"],answer:0,explanation:"Principal branch [−π/2, π/2] gives π/6."}],tip:"Always convert inverse values back into the principal range before answering."},"maths:maths-c17":{summary:"Matrices covers matrix types, operations, transpose, symmetric matrices and elementary operations.",keyPoints:["Matrix: rectangular array; order m × n; entries aᵢⱼ.","Addition/subtraction: same order; scalar multiplication multiplies every entry.","Multiplication: (m×n)·(n×p) = m×p; row × column; NOT commutative in general.","Transpose: swap rows/columns; (AB)ᵀ = BᵀAᵀ; symmetric if A = Aᵀ, skew if A = −Aᵀ.","Elementary row operations: swap rows, scale a row, add a multiple of one row to another."],formulas:[{name:"Transpose product",formula:"(AB)ᵀ = BᵀAᵀ"},{name:"Symmetric condition",formula:"A = Aᵀ"}],glossary:[{term:"Order of a matrix",def:"Rows × columns of the matrix.",hindi:"कोटि"},{term:"Skew-symmetric",def:"Matrix with Aᵀ = −A; diagonal entries zero.",hindi:"विषम-सममित"}],mistakes:["Multiplying matrices of incompatible orders (columns of A ≠ rows of B).","Assuming AB = BA — matrix multiplication is not commutative."],pyqs:[{q:"If A is 2×3 and B is 3×4, then AB has order:",options:["2×4","3×3","4×2","3×4"],answer:0,explanation:"Inner dimensions (3) match; result is outer 2×4."},{q:"For a skew-symmetric matrix, the diagonal entries are:",options:["zero","one","equal to off-diagonal","arbitrary"],answer:0,explanation:"aᵢᵢ = −aᵢᵢ ⇒ each diagonal entry is 0."}],tip:"Check dimension compatibility before any multiplication — the fastest way to lose marks otherwise."},"maths:maths-c18":{summary:"Determinants covers determinant properties, minors, cofactors, adjoints, inverses and Cramer's rule.",keyPoints:["|A| for 2×2: ad − bc; for 3×3 expand along any row/column with sign pattern.","Properties: |AB| = |A||B|; |Aᵀ| = |A|; swapping rows flips sign; identical rows ⇒ 0.","Minor Mᵢⱼ: determinant after deleting row i, column j; cofactor Cᵢⱼ = (−1)^(i+j) Mᵢⱼ.","Inverse: A⁻¹ = adj(A)/|A|, exists when |A| ≠ 0 (non-singular).","Cramer's rule solves systems: x = Dₓ/D etc.; area of triangle via determinant."],formulas:[{name:"2×2 determinant",formula:"|A| = ad − bc"},{name:"Inverse",formula:"A⁻¹ = adj(A) / |A|"},{name:"Triangle area",formula:"Area = ½ |x₁(y₂−y₃) + x₂(y₃−y₁) + x₃(y₁−y₂)|"}],glossary:[{term:"Cofactor",def:"Signed minor (−1)^(i+j)Mᵢⱼ.",hindi:"सहखंड"},{term:"Adjoint",def:"Transpose of the cofactor matrix.",hindi:"सहखंडज"},{term:"Singular matrix",def:"Matrix with |A| = 0 — no inverse.",hindi:"व्युत्क्रमणीय नहीं"}],mistakes:["Forgetting the (−1)^(i+j) sign in cofactors.","Dividing by |A| = 0 when inverting a singular matrix."],pyqs:[{q:"A matrix is singular when:",options:["|A| = 0","|A| = 1","A = Aᵀ","A is symmetric"],answer:0,explanation:"Zero determinant means no inverse exists."},{q:"|AB| equals:",options:["|A||B|","|A|+|B|","|A|−|B|","|BA| only if square"],answer:0,explanation:"Determinants multiply: |AB| = |A|·|B|."}],tip:"Row/column operations that create zeros make 3×3 expansion far faster — use them."},"maths:maths-c19":{summary:"Continuity and Differentiability covers continuity, differentiability, the chain rule and logarithmic differentiation.",keyPoints:["Continuity at a: lim_{x→a} f(x) = f(a); polynomials continuous everywhere.","Differentiable ⇒ continuous; the converse is false (e.g. |x| at 0).","Chain rule: dy/dx = dy/du · du/dx.","Implicit differentiation: differentiate both sides w.r.t. x, solving for dy/dx.","Logarithmic differentiation: ln both sides for products/powers (x^x, a^f(x))."],formulas:[{name:"Chain rule",formula:"dy/dx = dy/du · du/dx"},{name:"x^x derivative",formula:"d/dx xˣ = xˣ(1 + ln x)"}],glossary:[{term:"Continuity",def:"No breaks — limit equals function value.",hindi:"सांतत्य"},{term:"Differentiability",def:"Derivative exists — smooth, unique tangent.",hindi:"अवकलनीयता"}],mistakes:["Saying continuous functions are always differentiable (|x| breaks it).","Forgetting the inner derivative in the chain rule."],pyqs:[{q:"f(x) = |x| at x = 0 is:",options:["continuous but not differentiable","differentiable","neither","discontinuous"],answer:0,explanation:"The two-sided limit exists but the tangent isn't unique."},{q:"d/dx (sin 2x) equals:",options:["2 cos 2x","cos 2x","2 sin 2x","−2 cos 2x"],answer:0,explanation:"Chain rule: cos 2x × 2 = 2 cos 2x."}],tip:"Continuity questions: compute the left and right limits, then compare to f(a)."},"maths:maths-c20":{summary:"Application of Derivatives applies calculus to rates, tangents, monotonicity and maxima-minima.",keyPoints:["dy/dx = rate of change; 'rate of change of x w.r.t. time' uses the chain rule.","Tangent slope at x₀ = f'(x₀); normal slope = −1/f'(x₀).","f increasing where f'(x) > 0; decreasing where f'(x) < 0.","Maxima/minima: critical points f'(x) = 0; second derivative test: f'' < 0 max, f'' > 0 min.","Word problems: write the quantity to optimise, one variable, then differentiate."],formulas:[{name:"Tangent slope",formula:"m = f'(x₀)"},{name:"Normal slope",formula:"m = −1/f'(x₀)"},{name:"Second derivative test",formula:"f''(x₀) < 0 ⇒ max; > 0 ⇒ min"}],glossary:[{term:"Critical point",def:"Where f'(x) = 0 or doesn't exist.",hindi:"क्रांतिक बिंदु"},{term:"Monotonic",def:"Consistently increasing or decreasing on an interval.",hindi:"एकदिष्ट"}],mistakes:["Forgetting to verify maxima vs minima with the second derivative.","Answering 'derivative = 0' without checking endpoint values in closed-interval problems."],pyqs:[{q:"The maximum of f(x) = −x² + 4x occurs at:",options:["x = 2","x = 0","x = 4","x = −2"],answer:0,explanation:"f'(x) = −2x + 4 = 0 ⇒ x = 2; f'' = −2 < 0 confirms max."},{q:"A function is increasing where:",options:["f'(x) > 0","f'(x) < 0","f'(x) = 0","f''(x) > 0"],answer:0,explanation:"Positive derivative means rising function."}],tip:"Optimisation: endpoints and critical points both candidates — always compare."},"maths:maths-c21":{summary:"Integrals covers integration techniques — substitution, parts, partial fractions and definite integrals.",keyPoints:["Integration reverses differentiation; + C constant for indefinite integrals.","Substitution: choose u = inner function, du = u' dx.","By parts: ∫u dv = uv − ∫v du — choose u via ILATE (Inverse, Log, Algebra, Trig, Exp).","Partial fractions decompose rational functions before integrating.","Definite integrals: Newton-Leibniz; properties ∫₀ᵃ f = ∫₀ᵃ f(a−x); odd functions integrate to 0 on symmetric limits."],formulas:[{name:"Integration by parts",formula:"∫u dv = uv − ∫v du"},{name:"Power rule",formula:"∫xⁿ dx = xⁿ⁺¹/(n+1) + C"},{name:"Symmetry property",formula:"∫₋ₐᵃ f(x) dx = 0 for odd f"}],glossary:[{term:"Indefinite integral",def:"Family of antiderivatives, +C.",hindi:"अनिश्चित समाकल"},{term:"Definite integral",def:"Integral with limits, giving an area value.",hindi:"निश्चित समाकल"}],mistakes:["Choosing u poorly in by-parts — ILATE order prevents it.","Forgetting the +C on indefinite integrals."],pyqs:[{q:"∫x³ dx equals:",options:["x⁴/4 + C","3x² + C","x² + C","4x³ + C"],answer:0,explanation:"Power rule: x⁴/4 + C."},{q:"∫₀¹ x dx equals:",options:["1/2","1","0","2"],answer:0,explanation:"[x²/2]₀¹ = 1/2."}],tip:"In by-parts, ILATE decides u — Inverse/Log first, Exponential last."},"maths:maths-c22":{summary:"Application of Integrals uses integration to find areas under and between curves.",keyPoints:["Area under y = f(x) from a to b: ∫ₐᵇ f(x) dx (above the x-axis).","Area between curves: ∫ (upper − lower) dx over the intersection interval.","Find intersection points by solving f(x) = g(x).","Symmetry can halve the work (e.g. area of a circle via quadrant)."],formulas:[{name:"Area under curve",formula:"A = ∫ₐᵇ f(x) dx"},{name:"Area between curves",formula:"A = ∫ₐᵇ [f(x) − g(x)] dx, f ≥ g"}],glossary:[{term:"Definite integral as area",def:"Signed area between curve and axis.",hindi:"क्षेत्रफल"}],mistakes:["Ignoring which curve is on top — integrate (upper − lower).","Using intersection limits when the region is bounded by axes too."],pyqs:[{q:"The area enclosed by y = x² and the x-axis from x = 0 to 1 is:",options:["1/3","1/2","1","2/3"],answer:0,explanation:"∫₀¹ x² dx = 1/3."}],tip:"Sketch the region first — 'upper minus lower' is only valid after knowing the layout."},"maths:maths-c23":{summary:"Differential Equations covers order, degree, and solution methods — variable separable, homogeneous, linear.",keyPoints:["Order: highest derivative; degree: power of the highest derivative (after clearing radicals).","Variable separable: dy/dx = f(x)g(y) → separate and integrate.","Homogeneous: dy/dx = f(y/x); substitute y = vx.","Linear first order: dy/dx + P(x)y = Q(x); integrating factor e^∫P dx.","Solutions: general (with constants) vs particular (with initial conditions)."],formulas:[{name:"Integrating factor",formula:"IF = e^{∫P dx}"},{name:"Linear DE solution",formula:"y·IF = ∫ Q·IF dx + C"}],glossary:[{term:"Order of a DE",def:"Highest derivative order present.",hindi:"कोटि"},{term:"Integrating factor",def:"Multiplier making a linear DE exact.",hindi:"समाकलन गुणक"}],mistakes:["Mixing order and degree — degree is the power, not the number of derivatives.","Forgetting the constant when integrating (it defines the general solution)."],pyqs:[{q:"The order of (y'')² + y' = 0 is:",options:["2","1","4","0"],answer:0,explanation:"Order = highest derivative = 2 (degree is 2, the power)."},{q:"dy/dx = x is solved as:",options:["y = x²/2 + C","y = x + C","y = 2x + C","y = x² + C"],answer:0,explanation:"Integrate both sides: y = x²/2 + C."}],tip:"Read 'order' vs 'degree' carefully — they are usually different numbers."},"maths:maths-c24":{summary:"Vector Algebra covers vector operations, dot and cross products and scalar triple products.",keyPoints:["Vector: magnitude + direction; unit vector â = a/|a|.","Dot product a·b = |a||b|cosθ = a₁b₁ + a₂b₂ + a₃b₃; zero ⇒ perpendicular.","Cross product a×b = |a||b|sinθ n̂; magnitude = parallelogram area.","Projection of a on b = (a·b)/|b|.","Scalar triple product [a b c] = a·(b×c); zero ⇒ coplanar vectors."],formulas:[{name:"Dot product",formula:"a·b = |a||b| cosθ"},{name:"Cross product",formula:"|a×b| = |a||b| sinθ"},{name:"Projection",formula:"proj_b(a) = (a·b)/|b|"}],glossary:[{term:"Unit vector",def:"Vector of magnitude 1 along a direction.",hindi:"इकाई सदिश"},{term:"Coplanar",def:"Vectors lying in one plane ([a b c] = 0).",hindi:"समतलीय"}],mistakes:["Using the dot product formula where the cross product is needed.","Forgetting a×b is perpendicular to both a and b (right-hand rule)."],pyqs:[{q:"a·b = 0 means the vectors are:",options:["perpendicular","parallel","equal","opposite"],answer:0,explanation:"cosθ = 0 ⇒ θ = 90°."},{q:"|a×b| equals:",options:["area of the parallelogram","length of a","length of b","a·b"],answer:0,explanation:"Cross-product magnitude is the parallelogram area."}],tip:"Dot gives a scalar (cos), cross gives a vector (sin) — remember by the cosine/sine."},"maths:maths-c25":{summary:"Three Dimensional Geometry covers direction cosines, lines, planes, angles and distances in space.",keyPoints:["Direction cosines l, m, n satisfy l² + m² + n² = 1; direction ratios are proportional to them.","Line equations: vector r = a + λb or Cartesian (x−x₁)/l = (y−y₁)/m = (z−z₁)/n.","Angle between lines: cosθ = |l₁l₂ + m₁m₂ + n₁n₂|; parallel when ratios proportional.","Plane: ax + by + cz + d = 0 with normal (a,b,c); intercept form x/a + y/b + z/c = 1.","Distance of point to plane: |ax₁+by₁+cz₁+d|/√(a²+b²+c²); angle between planes via normals."],formulas:[{name:"Direction cosine rule",formula:"l² + m² + n² = 1"},{name:"Point-plane distance",formula:"d = |ax₁ + by₁ + cz₁ + d| / √(a² + b² + c²)"},{name:"Line equation",formula:"(x−x₁)/l = (y−y₁)/m = (z−z₁)/n"}],glossary:[{term:"Direction cosines",def:"Cosines of angles a line makes with the axes.",hindi:"दिक्-कोसाइन"},{term:"Normal",def:"Vector perpendicular to a plane.",hindi:"अभिलंब"}],mistakes:["Using direction ratios as if they were direction cosines without normalising.","Forgetting the absolute value in distance-to-plane questions."],pyqs:[{q:"The distance of (1, 2, 2) from the plane x + y + z = 0 is:",options:["5/√3","√3/5","5","3/√5"],answer:0,explanation:"|1+2+2|/√3 = 5/√3."},{q:"For direction cosines, l² + m² + n² equals:",options:["1","0","3","√3"],answer:0,explanation:"Unit normalisation forces the sum of squares to 1."}],tip:"Angles between lines and planes: use the direction/normal vectors, then cosθ formula."},"maths:maths-c26":{summary:"Linear Programming optimises a linear objective under linear constraints on the feasible region.",keyPoints:["Objective function: maximise/minimise Z = ax + by; constraints are linear inequalities.","Feasible region: intersection of all half-planes; optimum occurs at a corner point.","Corner point method: evaluate Z at every vertex; choose the best.","Unbounded regions: check whether the optimum is truly attained (test a larger value).","Integer programming: examine integer points near the optimum corner."],formulas:[{name:"Corner point method",formula:"Optimum of a linear function on a polygon occurs at a vertex"}],glossary:[{term:"Feasible region",def:"Region satisfying all constraints.",hindi:"सुसंगत क्षेत्र"},{term:"Objective function",def:"Linear function to optimise.",hindi:"उद्देश्य फलन"}],mistakes:["Picking an interior point instead of a corner — the optimum is at a vertex.","Mis-shading the feasible region from one wrong inequality."],pyqs:[{q:"In an LPP, the maximum of Z occurs at:",options:["a corner point","the origin always","any interior point","the y-axis only"],answer:0,explanation:"The fundamental theorem of LP: optimum at a vertex."}],tip:"Sketch constraints, shade the feasible region, list the corners, test each — mechanical and safe."},"maths:maths-c27":{summary:"Probability (Class 12) covers conditional probability, Bayes' theorem, random variables and binomial distributions.",keyPoints:["Conditional probability: P(A|B) = P(A∩B)/P(B).","Bayes' theorem: reverse conditional probabilities with prior weights.","Random variable X: maps outcomes to numbers; expectation E(X) = Σx P(x).","Variance Var(X) = E(X²) − [E(X)]².","Binomial: n trials, success p; P(X=r) = nCr p^r q^(n−r); mean np, variance npq."],formulas:[{name:"Conditional probability",formula:"P(A|B) = P(A∩B)/P(B)"},{name:"Binomial",formula:"P(X=r) = nCr p^r q^(n−r)"},{name:"Binomial mean/var",formula:"μ = np, σ² = npq"}],glossary:[{term:"Conditional probability",def:"Probability of A given B has occurred.",hindi:"प्रतिबंधी प्रायिकता"},{term:"Random variable",def:"Numerical outcome of a random experiment.",hindi:"यादृच्छिक चर"}],mistakes:["Using P(A∩B) = P(A)P(B) for dependent events — only valid when independent.","Confusing binomial with geometric distributions in word problems."],pyqs:[{q:"For a binomial with n = 10, p = 0.5, the mean is:",options:["5","2.5","10","0.5"],answer:0,explanation:"np = 10 × 0.5 = 5."},{q:"E(X²) − [E(X)]² gives:",options:["variance","mean","standard deviation","covariance"],answer:0,explanation:"That's the computational form of variance."}],tip:"Bayes: list the 'prior' probabilities and their conditional branches, then apply the formula."}},u={...c,...m,...d,...p};function f(e,a){const i=u[`${e}:${a}`];return i||h(e,a)}function h(e,a){const i=l(e),n=r(e,a),t=n?.name??"this chapter",s=n?.topics??[];return{summary:`${t} is a core ${i?.name??"subject"} chapter in the Class ${n?.class??11} NCERT syllabus. This notebook breaks it into the exact topics ${e==="biology"?"NEET":"your exam"} keeps asking about.`,keyPoints:[`Read the full NCERT text of “${t}” once — every line can seed a question.`,...s.slice(0,4).map(o=>`Master “${o.name}” — it is a repeatedly asked area.`),"Write the definitions in your own words; direct NCERT lines are favoured in exams."],formulas:e==="maths"?[{name:"Practice formula",formula:"Repetition is the master formula — solve 10 problems daily."}]:[{name:"Key relation",formula:"Check the NCERT text for the exact statement and units."}],glossary:[{term:t,def:`The chapter “${t}” covers ${s.map(o=>o.name).join(", ")||"its core ideas"}.`}],mistakes:["Skipping the NCERT definitions and jumping straight to question banks.","Ignoring units / notation specific to this chapter."],pyqs:[],tip:`Revise ${t} in short 20-minute sessions; its topics carry steady weightage.`}}function y(e){const i={neet:["Use spaced repetition for biology diagrams — 10 mins daily beats 2 hours on weekends.","NEET favours NCERT lines: read the exact statement twice before attempting PYQs.","For numericals, write the formula first, then substitute units — half your errors vanish.","Revise Chemistry in the morning when organic reaction mechanisms feel easier to recall.","Do one 45-minute mixed-topic PYQ drill every third day to train exam stamina."],jee:["JEE rewarders are the ones who practise — aim for 10 mixed numericals a day, timed.","Master the standard integrals and differentiation rules cold; they save minutes per question.","For Maths, write the approach before calculating — partial marks love clean method lines.","Physics theory in NCERT, practice from problems: concepts first, speed later.","Revise formula sheets every Sunday; spaced revision beats last-month cramming."]}[e],n=Math.floor(Date.now()/864e5);return i[n%i.length]}function b(e){return e==="neet"?"Medical":"Engineering"}export{b as a,f as g,y as s};
